function renderBoutique(){let p=state.progress,need=xpNeeded(p.level),pct=Math.min(100,p.xp/need*100),track=$('.xp-track'),query=($('#shopSearch')?.value||'').trim().toLowerCase(),category=$('#shopCategory')?.value||'all';$('#boutiqueLevel').textContent=p.level;$('#levelTitle').textContent=levelTitles[Math.min(p.level-1,levelTitles.length-1)];$('#xpLabel').textContent=`${p.xp} / ${need} XP`;$('#nextLevelLabel').textContent='Next: '+levelTitles[Math.min(p.level,levelTitles.length-1)];$('#xpFill').style.width=pct+'%';track.setAttribute('role','progressbar');track.setAttribute('aria-label','Level progress');track.setAttribute('aria-valuenow',Math.round(pct));track.setAttribute('aria-valuemin','0');track.setAttribute('aria-valuemax','100');$('#collectionCount').textContent=`${p.owned.length} owned`;let visible=shop.filter(item=>(category==='all'||item.type===category)&&(!query||`${item.name} ${item.desc} ${item.type}`.toLowerCase().includes(query)));$('#shopItems').innerHTML=visible.length?visible.map(item=>{let owned=p.owned.includes(item.id),equipped=p.equipped[item.type]===item.id,locked=p.level<item.level,price=applyEmpireDiscount(item.price,'boutique'),label=locked?`Locked · Level ${item.level}`:item.configurable?(owned?'Customize':'Configure'):equipped?'Equipped':owned?'Equip':`Buy · ${money(price)}`;return `<article class="shop-item ${equipped?'equipped':''}"><div class="shop-art art-${item.id}" aria-hidden="true">${item.symbol}</div><div class="shop-copy"><small>${item.type}${item.configurable?' · customizable':''}</small><h2>${item.name}</h2><p>${item.desc}</p><button data-shop="${item.id}" ${locked||equipped&&!item.configurable?'disabled':''}>${label}</button></div></article>`}).join(''):'<p class="shop-empty">No collectibles match that search.</p>'}
