let activeHouseFloor=1;
function houseTier(){return [...houseTiers].reverse().find(t=>state.progress.level>=t.level)||houseTiers[0]}
function gameUnlockLevel(name){return houseTiers.find(t=>t.games.includes(name))?.level||1}
function maxBet(){return houseTier().maxBet}
function renderHouseFloors(){let host=$('#houseFloorButtons');if(!host)return;host.innerHTML=[...houseFloors].reverse().map(floor=>{let locked=state.progress.level<floor.level,active=activeHouseFloor===floor.level;return `<button class="house-floor-entry ${locked?'locked':''} ${active?'active':''}" style="--floor-position:${floor.position}" data-house-floor="${floor.level}" aria-disabled="${locked}"><span><small>${locked?`Unlocks at Level ${floor.level}`:`Level ${floor.level} access`}</small><strong>${floor.name}</strong><em>${floor.tagline}</em></span><b>${locked?'◇':'Enter →'}</b></button>`}).join('')}
function enterHouseFloor(level){let floor=houseFloors.find(item=>item.level===level);if(!floor)return;if(state.progress.level<level){toast(`${floor.name} unlocks at Level ${level}.`);return}activeHouseFloor=level;refreshHomeLibrary(level);document.body.dataset.houseFloor=floor.theme;showDashboard();updateProgressionUi();toast(`${floor.name} selected.`)}
function updateProgressionUi(){let tier=houseTier(),cap=Number.isFinite(tier.maxBet)?money(tier.maxBet):'Unlimited',next=houseTiers.find(t=>t.level>state.progress.level),card=$('#houseTierCard');if(card)card.innerHTML=`<div><small>Current house access</small><strong>${tier.name}</strong><span>Maximum wager: ${cap}</span></div><div><small>${next?'Next access tier':'Top membership reached'}</small><strong>${next?`Level ${next.level} · ${next.name}`:'Dorra Royal'}</strong><span>${next?`${next.games.length?next.games.map(g=>osGameNames[g]||g).join(', ')+' · ':''}higher betting limit`:'Every table and unlimited wagering unlocked'}</span></div>`;$$('[data-game]').forEach(button=>{let level=gameUnlockLevel(button.dataset.game),locked=state.progress.level<level;button.classList.toggle('progression-locked',locked);button.setAttribute('aria-disabled',String(locked));button.dataset.unlockLevel=locked?level:''});let capValue=maxBet();Object.keys(state.bets).forEach(key=>state.bets[key]=Math.min(state.bets[key],capValue));if($('#monteBet'))$('#monteBet').textContent=money(state.bets.monte);if($('#memoryBet'))$('#memoryBet').textContent=money(state.bets.memory)}
const floorProgressionBase=updateProgressionUi;updateProgressionUi=function(){floorProgressionBase();renderHouseFloors();refreshHomeLibrary()};
