function resetRaceVisual(){$$('.race-horse').forEach(h=>{h.style.setProperty('--x','0%');h.classList.remove('picked','winner')});$$('.race-lane').forEach((lane,i)=>lane.classList.toggle('selected-lane',i===state.raceChoice));$('#raceProgress').style.width='0%';$('#raceDistance').textContent='1,600m';$('#raceStage').textContent='At the gates';$('#startingGate').classList.remove('open');$('#raceTrack').classList.remove('race-live')}
function raceWait(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
async function runEnhancedRace(){let bet=state.bets.racing,choice=state.raceChoice;if(choice===null||state.raceRunning||!afford(bet))return;state.raceRunning=true;state.balance-=bet;save();$('#raceResults').hidden=true;$('#raceStartBtn').disabled=true;$$('#raceRunners button').forEach(b=>b.disabled=true);resetRaceVisual();$$('.race-horse')[choice].classList.add('picked');$('#raceTrack').classList.add('race-live');for(let count=3;count>0;count--){$('#raceMessage').innerHTML=`<strong class="countdown">${count}</strong><span>Stand by for the start</span>`;tone(300+count*90,.08);await raceWait(650)}$('#startingGate').classList.add('open');$('#raceMessage').innerHTML='<strong>They’re off!</strong><span>Dorra Downs Race 10 is underway</span>';tone(760,.14);let winner=weightedRaceWinner(),others=raceHorses.map((_,i)=>i).filter(i=>i!==winner).sort(()=>Math.random()-.5),finalOrder=[winner,...others],start=performance.now(),duration=matchMedia('(prefers-reduced-motion: reduce)').matches?5200:9200,lastCall='',lastBeat=0;
  await new Promise(resolve=>{function frame(now){let t=Math.min(1,(now-start)/duration),stage=t<.22?'Breaking from the gates':t<.52?'Along the back straight':t<.76?'Rounding the final bend':t<.92?'Inside the final 400m':'Sprint to the line',distance=Math.max(0,Math.round((1600*(1-t))/50)*50);$('#raceStage').textContent=stage;$('#raceDistance').textContent=distance?`${distance.toLocaleString()}m`:'Finish';$('#raceProgress').style.width=`${t*100}%`;let positions=raceHorses.map((h,i)=>{let surge=Math.sin(t*15+i*1.73)*5*(1-t),style=(i%3-1)*Math.sin(t*Math.PI)*4,finishGap=finalOrder.indexOf(i)*3.2*Math.pow(t,4),progress=4+t*87+surge+style-finishGap;if(i===winner)progress+=Math.pow(t,5)*3;let horse=$$('.race-horse')[i];horse.style.setProperty('--x',`${Math.max(0,Math.min(91,progress))}%`);return {i,progress}}).sort((a,b)=>b.progress-a.progress);let place=positions.findIndex(p=>p.i===choice)+1,leader=positions[0].i,call=t<.12?'The field settles into stride':t>.9?`${raceHorses[leader].name} drives for the line`:`${raceHorses[leader].name} leads · ${raceHorses[choice].name} is ${ordinal(place)}`;if(call!==lastCall){$('#raceMessage').innerHTML=`<strong>${call}</strong><span>${stage}</span>`;lastCall=call}if(now-lastBeat>700&&t<.95){tone(150+t*120,.035);lastBeat=now}if(t<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)});
  let horses=$$('.race-horse');horses[winner].classList.add('winner');$('#raceTrack').classList.remove('race-live');$('#raceStage').textContent='Official result';let won=choice===winner,payout=won?Math.floor(bet*raceHorses[choice].odds):0;if(won)state.balance+=payout;$('#raceWinner').textContent=`${raceHorses[winner].name} wins`;$('#raceOrder').innerHTML=finalOrder.map((i,p)=>`<li class="${i===choice?'your-result':''}"><b>${p+1}</b><span>${raceHorses[i].name}${i===choice?' · Your bet':''}</span><em>${raceHorses[i].odds.toFixed(2)}</em></li>`).join('');$('#raceResults').hidden=false;$('#raceMessage').innerHTML=`<strong>${won?'Winner! '+money(payout)+' returned':raceHorses[choice].name+' finished '+ordinal(finalOrder.indexOf(choice)+1)}</strong><span>${raceHorses[winner].name} wins Race 10</span>`;state.raceRunning=false;$('#raceStartBtn').disabled=false;$$('#raceRunners button').forEach(b=>b.disabled=false);let msg=`${raceHorses[winner].name} wins — ${won?'paid '+money(payout):raceHorses[choice].name+' finished '+ordinal(finalOrder.indexOf(choice)+1)}.`;log('Dorra Downs: '+msg,won,'Horse Racing',bet);tone(won?920:210,.3)
}
/* Dorra House rooms, daily programme, and permanent trophies */
function localDate(){return new Date().toISOString().slice(0,10)}
function ensureDaily(){let today=localDate(),d=state.progress.daily;if(!d||d.date!==today)state.progress.daily={date:today,sessions:0,wins:0,games:[],bonusClaimed:false};state.progress.daily.games??=[];return state.progress.daily}
function dailyObjectives(){let d=ensureDaily();return [['Play 3 rounds',Math.min(d.sessions,3),3],['Win 2 rounds',Math.min(d.wins,2),2],['Visit 3 different tables',Math.min(d.games.length,3),3]]}
function dailyObjectivesHTML(){return dailyObjectives().map(([label,value,target])=>`<div class="objective"><span class="objective-mark">${value>=target?'✓':'◇'}</span><div><strong>${label}</strong><i><b style="width:${value/target*100}%"></b></i></div><em>${value} / ${target}</em></div>`).join('')}
function collectionSnapshot(){let p=state.progress,items=shop.filter(x=>p.owned.includes(x.id)),vehicles=Object.values(p.vehicles||{});return {count:p.owned.length+vehicles.length,value:items.reduce((n,x)=>n+x.price,0)+vehicles.reduce((n,x)=>n+(x.price||0),0)}}
