function macOptionHTML(name,options,savedValue){return options.map((option,i)=>{let extra=macOptionPrice(options,option.name);return `<label><input type="radio" name="${name}" value="${option.name}" ${(savedValue===option.name||!savedValue&&i===0)?'checked':''}><span>${option.name}${extra?` <b>+${money(extra)}</b>`:''}</span></label>`}).join('')}
