function updateMacPreview(){let m=macModel(),finish=macValue('macFinish')||m.finishes[0][0],colour=m.finishes.find(x=>x[0]===finish)?.[1]||'#686866',wall=(macValue('macWallpaper')||'Emerald').toLowerCase();$('#macPreview').style.setProperty('--mac-finish',colour);$('#macPreview').className=`mac-preview chassis-${m.chassis}`;$('#macPreview .mac-screen').className=`mac-screen wallpaper-${wall} ${macValue('macDisplay')==='Nano-texture'?'nano-texture':''}`;$('#macConfigPrice').textContent=money(macPrice());$('#macConfigPurchase').textContent=state.progress.owned.includes(activeMacFamily)?'Save configuration':`Purchase · ${money(macPrice())}`}
function openMacConfigurator(id){activeMacFamily=macbookFamilies[id]?id:'macbookm5';let saved=state.progress.configurations[activeMacFamily]||{},models=macbookFamilies[activeMacFamily].models;activeMacModel=models.some(x=>x.id===saved.model)?saved.model:models[0].id;renderMacOptions(saved);let wall=$(`[name="macWallpaper"][value="${saved.wallpaper||'Emerald'}"]`);if(wall)wall.checked=true;$('#macConfigurator').hidden=false;document.body.classList.add('modal-open');updateMacPreview();setTimeout(()=>$('#macConfigurator .config-close').focus(),20)}
