function renderDorraOsHome(){let details=dorraDeviceDetails(),now=new Date(),hour=now.getHours();$('#dorraOsBalance').textContent=`${money(state.balance)} available`;$('#dorraOsDate').textContent=now.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});$('#dorraOsTitle').textContent=hour<12?'Good morning.':hour<18?'Good afternoon.':'Good evening.';$('#dorraOsDeviceName').textContent=details.name;$('#dorraOsTime').textContent=now.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});$('#dorraOsDevice').style.setProperty('--device',details.finish);$('#dorraOsScreen').className=`dorraos-screen wallpaper-${details.wallpaper}`;$('#dorraOs').classList.toggle('macbook-mode',dorraDeviceMode==='mac')}
