const osGameNames={blackjack:'Blackjack',roulette:'European Roulette',monte:'Three Card Monte',memory:'Memory Match',highlow:'High–Low',dice:'Lucky Dice',baccarat:'Baccarat',poker:'Three Card Poker',holdem:"Texas Hold'em",videopoker:'Video Poker',sicbo:'Sic Bo',slots:'House Slots',racing:'Dorra Downs'};
function dorraOsWallet(){let recent=state.history.slice(0,6),snap=collectionSnapshot(),claimed=state.progress.rewardDate===localDate();return `<div class="os-balance-card"><span>Available balance</span><strong>${money(state.balance)}</strong><small>Play money only · ${money(snap.value)} collection value</small></div><button class="os-row" data-os-action="reward" ${claimed&&state.balance>=5?'disabled':''}><i>+</i><span><strong>${claimed?'Daily credit claimed':'Claim daily credit'}</strong><small>${claimed?'Come back tomorrow':'Add $250 to your wallet'}</small></span><em>›</em></button><span class="os-section-label">Recent activity</span><div class="os-list">${recent.length?recent.map(item=>{let text=typeof item==='string'?item:item.text;return `<div class="os-row"><i>◆</i><span><strong>${osEscape(text.split(': ')[0])}</strong><small>${osEscape(text.split(': ').slice(1).join(': ')||'House ledger')}</small></span></div>`}).join(''):'<div class="os-empty">No transactions yet.</div>'}</div>`}
function dorraOsHouse(){return `<span class="os-section-label">Open a table</span><div class="os-list">${Object.entries(osGameNames).map(([id,name])=>{let record=state.stats.games?.[name]||state.stats.games?.[id],played=record?.sessions||record?.played||0;return `<button class="os-row" data-os-game="${id}"><i>${name.slice(0,1)}</i><span><strong>${name}</strong><small>${played?`${played} rounds recorded`:'Ready to play'}</small></span><em>›</em></button>`}).join('')}</div>`}
function dorraOsGarage(){let owned=cars.filter(car=>state.progress.vehicles[car.id]);return `<span class="os-section-label">${owned.length} vehicle${owned.length===1?'':'s'} owned</span><div class="os-list">${owned.length?owned.map(car=>{let saved=state.progress.vehicles[car.id],displayed=state.progress.displayVehicle===car.id;return `<button class="os-row" data-os-car="${car.id}"><i>◆</i><span><strong>${osEscape(car.brand)} ${osEscape(car.model)}</strong><small>${osEscape(car.trims[saved.trim]?.[0]||car.trims[0][0])}${displayed?' · On display':''}</small></span><em>${displayed?'✓':'›'}</em></button>`}).join(''):'<div class="os-empty">Your garage is empty.<br>Purchase a vehicle in the Motor Atrium.</div>'}</div>`}
function dorraOsMessages(){let phones=dorraPhoneIds(),vehicles=Object.keys(state.progress.vehicles||{}).length,unlocked=Object.values(state.progress.achievements||{}).filter(Boolean).length,messages=[['Dorra House','Welcome to DorraOS. Your private house companion is ready.'],['The Concierge',`${phones.length} phone${phones.length===1?' is':'s are'} registered to your collection.`],['Motor Atrium',vehicles?`${vehicles} vehicle${vehicles===1?' is':'s are'} currently in your garage.`:'Your first vehicle awaits in the Motor Atrium.'],['Hall of Fame',`${unlocked} achievement${unlocked===1?'':'s'} unlocked so far.`]];return `<span class="os-section-label">House messages</span><div class="os-list">${messages.map(([from,text],i)=>`<div class="os-row"><i>${i?from[0]:'D'}</i><span><strong>${from}</strong><small>${text}</small></span></div>`).join('')}</div>`}
function dorraOsSettings(){let active=dorraDeviceMode==='mac'?dorraActiveMac():dorraActivePhone(),ids=dorraDeviceMode==='mac'?dorraMacIds():dorraPhoneIds(),details=dorraDeviceDetails(),wallpapers=['Emerald','Oxblood','Midnight','Ivory'];return `<div class="os-setting"><span>Active device</span><div class="os-choice">${ids.map(id=>{let device=dorraDeviceMode==='mac'?dorraMacDetails(id):dorraPhoneDetails(id);return `<button class="${id===active?'active':''}" data-os-device="${id}">${osEscape(device.name)}</button>`}).join('')}</div></div><div class="os-setting"><span>Wallpaper</span><div class="os-choice">${wallpapers.map(name=>`<button class="${details.wallpaper===name.toLowerCase()?'active':''}" data-os-wallpaper="${name}">${name}</button>`).join('')}</div></div><div class="os-setting"><span>House sound</span><div class="os-choice"><button class="${state.sound?'active':''}" data-os-sound="on">On</button><button class="${!state.sound?'active':''}" data-os-sound="off">Off</button></div></div><div class="os-setting"><span>About</span><small>${osEscape(details.name)} · Dorra OS 1.0<br>${osEscape(details.saved.storage||'Standard storage')} · ${osEscape(details.saved.finish||'Factory finish')}</small></div>`}
const dorraMarketCompanies=[{symbol:'DORRA',name:'Dorra Group',sector:'Hospitality',price:152.4,volatility:.016},{symbol:'MOTR',name:'Motria Systems',sector:'Mobility',price:78.32,volatility:.024},{symbol:'AURM',name:'Aurora Metals',sector:'Materials',price:43.18,volatility:.029},{symbol:'VANTA',name:'Vanta Dynamics',sector:'Technology',price:121.9,volatility:.032},{symbol:'HELIOS',name:'Helios Energy',sector:'Energy',price:67.05,volatility:.021}];
let dorraMarketUi={selected:'DORRA',side:'buy',qty:1,history:false},dorraMarketTimer=0;
function ensureDorraMarket(){if(!state.progress.market)state.progress.market={tick:0,holdings:{},trades:[],quotes:{}};let market=state.progress.market;market.holdings??={};market.trades??=[];market.quotes??={};market.tick??=0;dorraMarketCompanies.forEach((company,index)=>{if(!market.quotes[company.symbol]){let history=Array.from({length:24},(_,i)=>Number((company.price*(1+Math.sin(i*.58+index)*.006+(i-12)*.0007)).toFixed(2)));market.quotes[company.symbol]={price:company.price,open:history[0],history}}});return market}
function dorraMarketTick(persist=true){let market=ensureDorraMarket();market.tick++;dorraMarketCompanies.forEach((company,index)=>{let quote=market.quotes[company.symbol],cycle=Math.sin((market.tick+index*2.7)*.71)*company.volatility*.34,noise=(Math.random()-.5)*company.volatility*.48,shock=market.tick%19===0?(index%2?.012:-.009):0;quote.price=Number(Math.max(4,quote.price*(1+cycle+noise+shock)).toFixed(2));quote.history.push(quote.price);quote.history=quote.history.slice(-30)});if(persist)save('market')}
const dorraMarketMoney=value=>`${value<0?'-':''}$${Math.abs(value).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`;
function dorraMarketPortfolio(){let market=ensureDorraMarket(),invested=0,day=0;for(let [symbol,holding] of Object.entries(market.holdings)){let quote=market.quotes[symbol];invested+=holding.shares*quote.price;day+=holding.shares*(quote.price-quote.open)}return {cash:state.balance,invested,total:state.balance+invested,day}}
function dorraMarketIndex(){let market=ensureDorraMarket(),points=Array.from({length:24},(_,i)=>dorraMarketCompanies.reduce((sum,company)=>{let quote=market.quotes[company.symbol],history=quote.history,price=history[Math.max(0,history.length-24+i)]??quote.price;return sum+price/quote.open*1000},0)/dorraMarketCompanies.length),current=points.at(-1),open=points[0];return {points,current,open,change:current-open,pct:(current-open)/open*100}}
function dorraMarketChart(){let points=dorraMarketIndex().points,min=Math.min(...points),max=Math.max(...points),range=Math.max(.01,max-min),padding=range*.12;min-=padding;max+=padding;range=max-min;return points.map((value,i)=>`${i?'L':'M'}${(i/23*280).toFixed(1)},${(76-(value-min)/range*58).toFixed(1)}`).join(' ')}
function dorraMarketWatchRows(){let market=ensureDorraMarket();return dorraMarketCompanies.map(company=>{let quote=market.quotes[company.symbol],holding=market.holdings[company.symbol],change=(quote.price-quote.open)/quote.open*100,up=change>=0;return `<button class="market-row ${dorraMarketUi.selected===company.symbol?'selected':''}" data-market-stock="${company.symbol}"><i>${company.symbol[0]}</i><span><strong>${company.symbol}</strong><small>${company.name}${holding?.shares?` · ${holding.shares} owned`:''}</small></span><b>${dorraMarketMoney(quote.price)}<small>${company.sector}</small></b><em class="${up?'up':'down'}">${up?'+':''}${change.toFixed(2)}%</em><u>›</u></button>`}).join('')}
function dorraMarketOrderSheet(){let market=ensureDorraMarket(),company=dorraMarketCompanies.find(item=>item.symbol===dorraMarketUi.selected),quote=market.quotes[company.symbol],holding=market.holdings[company.symbol]||{shares:0,avg:0},qty=Math.max(1,Number(dorraMarketUi.qty)||1),total=Math.round(qty*quote.price),valid=dorraMarketUi.side==='buy'?state.balance>=total:holding.shares>=qty;return `<section class="market-order"><header><div><strong>${company.symbol}</strong><small>${company.name}</small></div><b>${dorraMarketMoney(quote.price)}<small>${holding.shares} shares owned</small></b><button data-market-close aria-label="Close order ticket">×</button></header><div class="market-side"><button class="${dorraMarketUi.side==='buy'?'active':''}" data-market-side="buy">Buy</button><button class="${dorraMarketUi.side==='sell'?'active':''}" data-market-side="sell">Sell</button></div><div class="market-qty"><span>Shares</span><div><button data-market-qty="-1" aria-label="Decrease shares">−</button><input data-market-input inputmode="numeric" value="${qty}" aria-label="Number of shares"><button data-market-qty="1" aria-label="Increase shares">+</button></div></div><div class="market-estimate"><span>Estimated ${dorraMarketUi.side==='buy'?'cost':'proceeds'}</span><strong>${dorraMarketMoney(total)}</strong></div><button class="market-review" data-market-submit ${valid?'':'disabled'}>${valid?`${dorraMarketUi.side==='buy'?'Buy':'Sell'} ${qty} share${qty===1?'':'s'}`:dorraMarketUi.side==='buy'?'Not enough cash':'Not enough shares'} <span>›</span></button><small class="market-disclaimer">Whole-dollar settlement · No real money</small></section>`}
function dorraMarketHistory(){let market=ensureDorraMarket();return `<section class="market-history"><header><h3>Trade history</h3><span>${market.trades.length?'<button data-market-clear>Clear</button>':''}<button data-market-history>Done</button></span></header>${market.trades.length?market.trades.map(trade=>`<div><i class="${trade.side}">${trade.side==='buy'?'B':'S'}</i><span><strong>${trade.side==='buy'?'Bought':'Sold'} ${trade.qty} ${trade.symbol}</strong><small>${new Date(trade.at).toLocaleString()}</small></span><b>${dorraMarketMoney(trade.total)}<small>@ ${dorraMarketMoney(trade.price)}</small></b></div>`).join(''):'<p>No trades yet. Choose a company to place your first simulated order.</p>'}</section>`}
function dorraOsMarkets(){let portfolio=dorraMarketPortfolio(),index=dorraMarketIndex(),up=index.change>=0,rate=dorraMarketRate();return `<div class="markets-shell"><header class="market-title"><span>Simulated market · ${rate.label}${rate.ms?` ${rate.ms/1000}s`:' · stopped'} <i></i></span><button data-market-tick>↻ Update</button></header><section class="market-portfolio"><div><span>Dorra Market Index</span><strong>${index.current.toFixed(2)}</strong><small class="${up?'up':'down'}">${up?'+':''}${index.change.toFixed(2)} today · ${up?'+':''}${index.pct.toFixed(2)}%</small></div><svg viewBox="0 0 280 86" role="img" aria-label="Dorra simulated market index chart"><path d="M0 70H280" class="market-grid"/><path d="${dorraMarketChart()}" class="market-line"/></svg><footer><span>Portfolio <b>${dorraMarketMoney(portfolio.total)}</b></span><span>Cash · Invested <b>${dorraMarketMoney(portfolio.cash)} · ${dorraMarketMoney(portfolio.invested)}</b></span></footer></section><div class="market-list-head"><h3>Watchlist</h3><button data-market-history>History</button></div><div class="market-watch">${dorraMarketWatchRows()}</div>${dorraMarketUi.history?dorraMarketHistory():dorraMarketUi.selected?dorraMarketOrderSheet():''}</div>`}
