function dorraOsPerks(){let perks=ensureDorraPerks(),ownedCount=Object.keys(perks.owned).length;return `<div class="perks-shell"><section class="perks-hero"><span>House enhancements</span><strong>${ownedCount} perk${ownedCount===1?'':'s'} owned</strong><small>${money(state.balance)} available</small></section><div class="perks-heading"><h3>Available perks</h3><span>Permanent upgrades</span></div>${dorraPerkCatalog.map(perk=>{let owned=perks.owned[perk.id],available=!perk.requires||perks.owned[perk.requires],rate=dorraMarketRate(),rateIndex=dorraMarketRateOrder.findIndex(id=>dorraMarketRates[id]===rate);let ownedControl=perk.id==='market-accelerator'?`<div class="perk-controller"><header><span>Market speed</span><strong>${rate.label}${rate.ms?` · ${rate.ms/1000}s`:' · stopped'}</strong></header><input type="range" min="0" max="4" step="1" value="${rateIndex}" data-perk-rate-input aria-label="Market simulation speed"><div>${dorraMarketRateOrder.map(id=>`<span>${dorraMarketRates[id].label}</span>`).join('')}</div><small>Manual Update remains available while paused.</small></div>`:`<div class="perk-controller"><header><span>Slot control</span><strong>Tier unlocked</strong></header><small>All unlocked auto-spin lengths are selectable at House Slots.</small></div>`;let blocked=!available||state.balance<perk.price,reason=!available?'Purchase the previous Auto-Spin tier first.':state.balance<perk.price?'Earn more play money to unlock.':'Uses your Dorra wallet balance.';return `<article class="perk-card ${owned?'owned':''} ${!available?'locked':''}"><header><i>${perk.symbol}</i><div><small>${owned?'Owned':available?'DorraOS perk':'Tier locked'}</small><h3>${perk.name}</h3></div>${owned?'<b>✓</b>':''}</header><p>${perk.description}</p><ul>${perk.features.map(feature=>`<li>${feature}</li>`).join('')}</ul>${owned?ownedControl:`<button class="perk-buy" data-perk-buy="${perk.id}" ${blocked?'disabled':''}><span>${available?'Buy permanently':'Previous tier required'}</span><strong>${money(perk.price)}</strong></button><small class="perk-balance-note">${reason}</small>`}</article>`}).join('')}<section class="perks-future"><i>＋</i><div><strong>More perks coming</strong><small>New upgrades can be added to this catalogue.</small></div></section></div>`}
const dorraOsPerksV1=dorraOsPerks;
