$('#dorraOsAppBody').addEventListener('click',event=>{if($('#dorraOsAppTitle').textContent!=='Markets')return;let stock=event.target.closest('[data-market-stock]'),side=event.target.closest('[data-market-side]'),qtyButton=event.target.closest('[data-market-qty]'),close=event.target.closest('[data-market-close]'),history=event.target.closest('[data-market-history]'),clear=event.target.closest('[data-market-clear]'),tick=event.target.closest('[data-market-tick]'),submit=event.target.closest('[data-market-submit]');if(stock){dorraMarketUi.selected=stock.dataset.marketStock;dorraMarketUi.history=false;dorraMarketUi.qty=1;renderDorraMarketApp(true);return}if(side){dorraMarketUi.side=side.dataset.marketSide;renderDorraMarketApp(true);return}if(qtyButton){dorraMarketUi.qty=Math.max(1,Math.min(999,Number(dorraMarketUi.qty)+Number(qtyButton.dataset.marketQty)));renderDorraMarketApp(true);return}if(close){dorraMarketUi.selected='';renderDorraMarketApp(true);return}if(history){dorraMarketUi.history=!dorraMarketUi.history;renderDorraMarketApp(true);return}if(clear){ensureDorraMarket().trades=[];state.history=state.history.filter(item=>!String(typeof item==='string'?item:item.text).startsWith('Markets:'));save('market-history');renderDorraMarketApp(true);toast('Trade history cleared.');return}if(tick){dorraMarketTick();renderDorraMarketApp();return}if(submit&&!submit.disabled){let market=ensureDorraMarket(),symbol=dorraMarketUi.selected,quote=market.quotes[symbol],qty=Math.max(1,Math.floor(Number(dorraMarketUi.qty)||1)),total=Math.round(qty*quote.price),holding=market.holdings[symbol]||{shares:0,avg:0};if(dorraMarketUi.side==='buy'){if(total>state.balance){toast('Not enough cash for this order.');return}holding.avg=(holding.shares*holding.avg+total)/(holding.shares+qty);holding.shares+=qty;market.holdings[symbol]=holding;state.balance-=total}else{if(qty>holding.shares){toast('Not enough shares to sell.');return}holding.shares-=qty;state.balance+=total;if(holding.shares)market.holdings[symbol]=holding;else delete market.holdings[symbol]}market.trades.unshift({side:dorraMarketUi.side,symbol,qty,price:quote.price,total,at:Date.now()});market.trades=market.trades.slice(0,40);state.history.unshift({text:`Markets: ${dorraMarketUi.side==='buy'?'Bought':'Sold'} ${qty} ${symbol} for ${dorraMarketMoney(total)}.`});dorraMarketUi.qty=1;save('market-trade');renderDorraMarketApp(true);toast(`${dorraMarketUi.side==='buy'?'Purchase':'Sale'} completed.`)}});
$('#dorraOsAppBody').addEventListener('change',event=>{if(!event.target.matches('[data-market-input]'))return;dorraMarketUi.qty=Math.max(1,Math.min(999,Math.floor(Number(event.target.value)||1)));renderDorraMarketApp(true)});
$('#dorraOsAppBody').addEventListener('click',event=>{if($('#dorraOsAppTitle').textContent!=='Upgrades')return;let buy=event.target.closest('[data-perk-buy]');if(buy&&!buy.disabled){let perk=dorraPerkCatalog.find(item=>item.id===buy.dataset.perkBuy),perks=ensureDorraPerks();if(!perk||perks.owned[perk.id])return;if(perk.requires&&!perks.owned[perk.requires]){toast('Purchase the previous Auto-Spin tier first.');return}if(state.balance<perk.price){toast('Not enough play money for this perk.');return}state.balance-=perk.price;perks.owned[perk.id]={purchasedAt:Date.now(),price:perk.price};if(perk.id==='market-accelerator')perks.settings.marketRate='fast';save('perk-purchase');updateAutoSpin();openDorraOsApp('perks');toast(`${perk.name} unlocked.`)}});
