dorraMarketExtraCompanies.forEach(company=>{if(!dorraMarketCompanies.some(item=>item.symbol===company.symbol))dorraMarketCompanies.push(company)});
function ensureDorraOsApps(){state.progress.osApps??={owned:{}};state.progress.osApps.owned??={};return state.progress.osApps}
function dorraAppOwned(id){return !!ensureDorraOsApps().owned[id]}
const marketStoryTemplates={Hospitality:[['Luxury resort bookings exceed guidance',1],['Labour costs weigh on operating margins',-1]],Mobility:[['Fleet contract expands recurring revenue',1],['Safety recall raises near-term costs',-1]],Materials:[['Supply disruption lifts realised metal prices',1],['Input costs pressure quarterly margins',-1]],Technology:[['Enterprise product launch wins early demand',1],['Key customer delays software rollout',-1]],Energy:[['New capacity clears regulatory review',1],['Unplanned outage reduces production outlook',-1]],Industrials:[['Order backlog reaches a record level',1],['Factory downtime triggers guidance cut',-1]]};
function marketCreateEvent(market){let company=dorraMarketCompanies[Math.floor(Math.random()*dorraMarketCompanies.length)],templates=marketStoryTemplates[company.sector]||marketStoryTemplates.Technology,template=templates[Math.floor(Math.random()*templates.length)],lead=5+Math.floor(Math.random()*5);market.events.push({id:`${market.tick}-${company.symbol}-${Math.random().toString(36).slice(2,7)}`,symbol:company.symbol,headline:template[0],direction:template[1],magnitude:Number((.018+Math.random()*.045).toFixed(3)),confidence:Math.round(58+Math.random()*36),createdTick:market.tick,impactTick:market.tick+lead,applied:false});market.events=market.events.slice(-18)}
const ensureDorraMarketV1=ensureDorraMarket;
ensureDorraMarket=function(){let market=ensureDorraMarketV1();market.events??=[];market.regime??={name:'Normal',vol:1,remaining:12};market.session??=1;dorraMarketCompanies.forEach(company=>{let quote=market.quotes[company.symbol];quote.open??=quote.price;quote.high??=Math.max(...quote.history);quote.low??=Math.min(...quote.history);quote.volume??=Math.round(180000+Math.random()*850000);quote.prevClose??=quote.open;quote.fairValue??=company.price});return market};
function marketNormalRandom(){let u=1-Math.random(),v=1-Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
dorraMarketTick=function(persist=true){let market=ensureDorraMarket();market.tick++;if(--market.regime.remaining<=0){let roll=Math.random();market.regime=roll<.12?{name:'High volatility',vol:1.75,remaining:6+Math.floor(Math.random()*8)}:roll<.25?{name:'Quiet',vol:.62,remaining:8+Math.floor(Math.random()*10)}:{name:'Normal',vol:1,remaining:10+Math.floor(Math.random()*14)}}let factor=marketNormalRandom()*.0045*market.regime.vol;if(!market.events.some(event=>!event.applied)&&market.tick%4===0)marketCreateEvent(market);dorraMarketCompanies.forEach(company=>{let quote=market.quotes[company.symbol],noise=marketNormalRandom()*company.volatility*.17*market.regime.vol,reversion=Math.log(Math.max(1,quote.fairValue)/quote.price)*.018,eventReturn=market.events.filter(event=>!event.applied&&event.impactTick===market.tick&&event.symbol===company.symbol).reduce((sum,event)=>sum+event.direction*event.magnitude,0),logReturn=company.drift+factor*company.beta+noise+reversion+eventReturn;quote.price=Number(Math.max(3,quote.price*Math.exp(logReturn)).toFixed(2));quote.high=Math.max(quote.high,quote.price);quote.low=Math.min(quote.low,quote.price);quote.volume+=Math.round((90000+Math.random()*310000)*(1+Math.abs(logReturn)*18));quote.history.push(quote.price);quote.history=quote.history.slice(-48)});market.events.forEach(event=>{if(!event.applied&&event.impactTick<=market.tick){event.applied=true;event.appliedTick=market.tick}});if(market.tick&&market.tick%36===0){market.session++;dorraMarketCompanies.forEach(company=>{let q=market.quotes[company.symbol];q.prevClose=q.price;q.open=q.price;q.high=q.price;q.low=q.price;q.volume=0})}if(persist)save('market')};
function marketSpread(company){return Math.max(.01,ensureDorraMarket().quotes[company.symbol].price*(.0008+company.volatility*.035))}
dorraMarketWatchRows=function(){let market=ensureDorraMarket();return dorraMarketCompanies.map(company=>{let quote=market.quotes[company.symbol],holding=market.holdings[company.symbol],change=(quote.price-quote.open)/quote.open*100,up=change>=0,spread=marketSpread(company);return `<button class="market-row ${dorraMarketUi.selected===company.symbol?'selected':''}" data-market-stock="${company.symbol}"><i>${company.symbol[0]}</i><span><strong>${company.symbol}</strong><small>${company.name}${holding?.shares?` · ${holding.shares} owned`:''}</small></span><b>${dorraMarketMoney(quote.price)}<small>Bid ${(quote.price-spread/2).toFixed(2)} · Ask ${(quote.price+spread/2).toFixed(2)}</small></b><em class="${up?'up':'down'}">${up?'+':''}${change.toFixed(2)}%</em><u>›</u></button>`}).join('')};
dorraMarketOrderSheet=function(){let market=ensureDorraMarket(),company=dorraMarketCompanies.find(item=>item.symbol===dorraMarketUi.selected),quote=market.quotes[company.symbol],holding=market.holdings[company.symbol]||{shares:0,avg:0},qty=Math.max(1,Number(dorraMarketUi.qty)||1),spread=marketSpread(company),fill=quote.price+(dorraMarketUi.side==='buy'?spread/2:-spread/2),subtotal=qty*fill,fee=Math.max(1,subtotal*.001),total=Math.round((dorraMarketUi.side==='buy'?subtotal+fee:subtotal-fee)*100)/100,valid=dorraMarketUi.side==='buy'?state.balance>=total:holding.shares>=qty;return `<section class="market-order"><header><div><strong>${company.symbol}</strong><small>${company.name} · ${company.sector}</small></div><b>${dorraMarketMoney(quote.price)}<small>H ${quote.high.toFixed(2)} · L ${quote.low.toFixed(2)}</small></b><button data-market-close aria-label="Close order ticket">×</button></header><div class="market-fundamentals"><span>P/E <b>${company.pe.toFixed(1)}</b></span><span>Yield <b>${company.yield.toFixed(1)}%</b></span><span>Volume <b>${(quote.volume/1000).toFixed(0)}K</b></span></div><div class="market-side"><button class="${dorraMarketUi.side==='buy'?'active':''}" data-market-side="buy">Buy</button><button class="${dorraMarketUi.side==='sell'?'active':''}" data-market-side="sell">Sell</button></div><div class="market-qty"><span>Shares</span><div><button data-market-qty="-1">−</button><input data-market-input inputmode="numeric" value="${qty}" aria-label="Number of shares"><button data-market-qty="1">+</button></div></div><div class="market-estimate"><span>Estimated ${dorraMarketUi.side==='buy'?'cost':'proceeds'}<small>Fill ${dorraMarketMoney(fill)} · fee ${dorraMarketMoney(fee)}</small></span><strong>${dorraMarketMoney(total)}</strong></div><button class="market-review" data-market-submit ${valid?'':'disabled'}>${valid?`${dorraMarketUi.side==='buy'?'Buy':'Sell'} ${qty} share${qty===1?'':'s'}`:dorraMarketUi.side==='buy'?'Not enough cash':'Not enough shares'} <span>›</span></button><small class="market-disclaimer">Simulated market order · spread and 0.10% fee included · No real money</small></section>`};
function marketPublicNews(){let news=ensureDorraMarket().events.filter(event=>event.applied).slice(-3).reverse();return `<section class="market-news"><header><h3>Market news</h3><span>Public tape</span></header>${news.length?news.map(event=>`<div><b>${event.symbol}</b><span><strong>${event.headline}</strong><small>Price reaction ${event.direction>0?'+':''}${(event.direction*event.magnitude*100).toFixed(1)}% · simulated</small></span></div>`).join(''):'<p>No company news on the public tape yet.</p>'}</section>`}
const dorraOsMarketsV1=dorraOsMarkets;
dorraOsMarkets=function(){let html=dorraOsMarketsV1(),market=ensureDorraMarket(),rate=dorraMarketRate();return html.replace(/Simulated market · [^<]+/,`Session ${market.session} · ${market.regime.name} regime · ${rate.label}${rate.ms?` ${rate.ms/1000}s`:' · stopped'}`).replace('<div class="market-list-head">',`${marketPublicNews()}<div class="market-list-head">`)};
function appStoreRows(){return dorraOsStoreCatalog.map(app=>{let owned=dorraAppOwned(app.id);return `<article class="store-row"><i class="store-icon ${app.id}">${app.short}</i><div><strong>${app.name}</strong><small>${app.category} · ${app.description}</small><span>★ ${app.rating} · ${app.reviews} ratings</span></div><button data-store-app="${app.id}" ${app.coming?'disabled':''}>${app.coming?'SOON':owned?'OPEN':money(app.price)}</button></article>`}).join('')}
function dorraOsAppStore(){let owned=dorraAppOwned('bloomberg');return `<div class="store-shell"><header class="store-top"><div><small>Dorra OS</small><h2>Dorra App Store</h2></div><label>⌕ <input placeholder="Search apps" aria-label="Search apps"></label></header><nav><button class="active">Today</button><button>Apps</button><button>Purchased</button></nav><section class="store-feature"><small>FEATURED · FINANCE</small><div class="store-feature-title"><i class="store-icon bloomberg">BI</i><div><h3>Bloomberg Intelligence</h3><p>Advance market intelligence</p><span>Mock news · Simulated market</span></div><button data-store-app="bloomberg">${owned?'OPEN':money(50000)}</button></div><div class="store-rating"><span><b>4.8</b> out of 5</span><span><b>12+</b> Age</span><span><b>Finance</b> Category</span></div><div class="store-previews"><div><b>BREAKING</b><strong>News before the move</strong><small>Timed advance insight</small></div><div><b>WATCHLIST</b><strong>Impact countdowns</strong><small>Bullish and bearish signals</small></div><div><b>DETAIL</b><strong>Confidence scoring</strong><small>Outcomes are uncertain</small></div></div><p>Receive timed mock-news intelligence before a simulated company event reaches the market. Confidence and impact are estimates, not guarantees.</p><aside>ⓘ Not real financial advice. For simulation and entertainment only.</aside></section><h3 class="store-heading">More Apps for You</h3><div class="store-list">${appStoreRows()}</div></div>`}
const dorraOsAppStoreV1=dorraOsAppStore;
dorraOsAppStore=function(){return dorraOsAppStoreV1().replace('<small>Dorra OS</small>','<small>Software for your Dorra OS devices</small>').replace('<input placeholder="Search apps"','<input data-store-search placeholder="Search apps"').replace('<header class="store-top">','<header class="store-top"><button class="app-inline-back" data-os-inline-back aria-label="Return to DorraOS home">‹</button>').replace('<section class="store-feature">',`<section class="store-purpose"><i>A</i><span><strong>Install apps on Dorra OS</strong><small>Purchased apps appear on your Dorra OS Home Screen. Gameplay upgrades are sold separately in Upgrades.</small></span></section><section class="store-feature">`).replace('<div class="store-list">'+appStoreRows()+'</div>',`<div class="store-list">${dorraOsStoreCatalog.filter(app=>app.id!=='bloomberg').map(app=>`<article class="store-row" data-store-name="${app.name.toLowerCase()} ${app.category.toLowerCase()}"><i class="store-icon ${app.id}">${app.short}</i><div><strong>${app.name}</strong><small>${app.category} · ${app.description}</small><span>★ ${app.rating} · ${app.reviews} ratings</span></div><button data-store-app="${app.id}" ${app.coming?'disabled':''}>${app.coming?'SOON':dorraAppOwned(app.id)?'OPEN':money(app.price)}</button></article>`).join('')}</div>`)};
let bloombergUi={selected:null};
function bloombergCountdown(event){let left=Math.max(0,event.impactTick-ensureDorraMarket().tick),seconds=left*(dorraMarketRate().ms?dorraMarketRate().ms/1000:12);return left?`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.round(seconds%60)).padStart(2,'0')}`:'REPRICED'}
function dorraOsBloomberg(){if(!dorraAppOwned('bloomberg'))return `<div class="bi-locked"><i>BI</i><h2>Bloomberg Intelligence</h2><p>Purchase this app from the Dorra App Store to unlock advance market intelligence.</p><button data-open-store>Open App Store</button></div>`;let market=ensureDorraMarket();if(!market.events.length)marketCreateEvent(market);let events=market.events.slice().sort((a,b)=>(a.applied-b.applied)||(a.impactTick-b.impactTick)).slice(0,8),selected=events.find(event=>event.id===bloombergUi.selected)||events[0];bloombergUi.selected=selected?.id;let company=dorraMarketCompanies.find(item=>item.symbol===selected?.symbol),quote=company&&market.quotes[company.symbol];return `<div class="bi-shell"><header class="bi-top"><b>BI</b><div><strong>Bloomberg Intelligence</strong><small>Mock news · Simulated market</small></div><span><i></i> CONNECTED</span></header><div class="bi-ticker">${dorraMarketCompanies.slice(0,6).map(item=>{let q=market.quotes[item.symbol],pct=(q.price-q.open)/q.open*100;return `<span><b>${item.symbol}</b>${q.price.toFixed(2)} <em class="${pct>=0?'up':'down'}">${pct>=0?'▲':'▼'} ${Math.abs(pct).toFixed(2)}%</em></span>`}).join('')}</div><div class="bi-layout"><section class="bi-feed"><header><b>INTELLIGENCE FEED</b><span>ADVANCE + PUBLIC</span></header>${events.map(event=>`<button class="${event.id===selected?.id?'active':''}" data-bi-story="${event.id}"><small>${event.applied?'PUBLIC':'ADVANCE'}</small><strong>${event.headline}</strong><span><b>${event.symbol}</b><em class="${event.direction>0?'up':'down'}">${event.direction>0?'BULLISH ▲':'BEARISH ▼'}</em></span><time>${event.applied?'MOVED':'PRICE IMPACT IN '+bloombergCountdown(event)}</time></button>`).join('')}</section>${selected?`<article class="bi-detail"><small>${selected.applied?'PUBLIC NEWS':'ADVANCE INTELLIGENCE'}</small><h2>${selected.headline}</h2><div class="bi-metrics"><span>Affected<b>${selected.symbol}</b></span><span>Impact<b class="${selected.direction>0?'up':'down'}">${selected.direction>0?'Bullish ▲':'Bearish ▼'}</b></span><span>Confidence<b>${selected.confidence}%</b></span></div><section class="bi-countdown"><span>${selected.applied?'REALIZED MOVE':'PRICE IMPACT IN'}</span><strong>${selected.applied?`${selected.direction>0?'+':''}${(selected.direction*selected.magnitude*100).toFixed(1)}%`:bloombergCountdown(selected)}</strong><small>${selected.applied?'Event has reached the public tape':'Scheduled simulation event · timing pauses with market'}</small></section><h3>Insight summary</h3><p>${company.name} has a scheduled ${selected.direction>0?'positive':'negative'} company event. The model estimates a ${(selected.magnitude*100).toFixed(1)}% directional shock with ${selected.confidence}% confidence. Market noise, sector correlation and mean reversion can change the observed return.</p><footer><span>LAST ${quote.price.toFixed(2)}</span><span>RANGE ${quote.low.toFixed(2)}–${quote.high.toFixed(2)}</span><span>VOLUME ${(quote.volume/1000).toFixed(0)}K</span></footer></article>`:''}</div><footer class="bi-disclaimer">ⓘ Not real financial advice. Timing, confidence and price impact are simulated.</footer></div>`}
dorraOsApps.appstore=['App Store',dorraOsAppStore];dorraOsApps.bloomberg=['Bloomberg',dorraOsBloomberg];
const renderDorraOsHomeV1=renderDorraOsHome;renderDorraOsHome=function(){renderDorraOsHomeV1();let app=$('[data-installed-app="bloomberg"]');if(app)app.hidden=!dorraAppOwned('bloomberg')};
const openDorraOsAppV1=openDorraOsApp;openDorraOsApp=function(id){if(id==='bloomberg'&&!dorraAppOwned('bloomberg'))id='appstore';openDorraOsAppV1(id)};
$('#dorraOsAppBody').addEventListener('click',event=>{let store=event.target.closest('[data-store-app]'),story=event.target.closest('[data-bi-story]'),openStore=event.target.closest('[data-open-store]');if(openStore){openDorraOsApp('appstore');return}if(story){bloombergUi.selected=story.dataset.biStory;openDorraOsApp('bloomberg');return}if(store){let app=dorraOsStoreCatalog.find(item=>item.id===store.dataset.storeApp);if(!app||app.coming)return;if(dorraAppOwned(app.id)){openDorraOsApp(app.id);return}if(state.balance<app.price){toast(`You need ${money(app.price-state.balance)} more play money.`);return}state.balance-=app.price;ensureDorraOsApps().owned[app.id]={purchasedAt:Date.now(),price:app.price};state.history.unshift({text:`App Store: Purchased ${app.name} for ${money(app.price)}.`});save('app-purchase');renderDorraOsHome();openDorraOsApp(app.id);toast(`${app.name} installed.`)}});
$('#dorraOsAppBody').addEventListener('input',event=>{if(!event.target.matches('[data-store-search]'))return;let query=event.target.value.trim().toLowerCase();$$('.store-row[data-store-name]').forEach(row=>row.hidden=!!query&&!row.dataset.storeName.includes(query));let heading=$('.store-heading');if(heading)heading.textContent=query?'Search results':'More Apps for You'});
