// Capture market submissions so the displayed spread and fee exactly match wallet settlement.
$('#dorraOsAppBody').addEventListener('click',event=>{let submit=event.target.closest('[data-market-submit]');if(!submit||submit.disabled||$('#dorraOsAppTitle').textContent!=='Markets')return;event.stopImmediatePropagation();let market=ensureDorraMarket(),symbol=dorraMarketUi.selected,company=dorraMarketCompanies.find(item=>item.symbol===symbol),quote=market.quotes[symbol],qty=Math.max(1,Math.floor(Number(dorraMarketUi.qty)||1)),fill=quote.price+(dorraMarketUi.side==='buy'?marketSpread(company)/2:-marketSpread(company)/2),subtotal=qty*fill,fee=Math.max(1,subtotal*.001),total=Math.round((dorraMarketUi.side==='buy'?subtotal+fee:subtotal-fee)*100)/100,holding=market.holdings[symbol]||{shares:0,avg:0};if(dorraMarketUi.side==='buy'){if(total>state.balance){toast('Not enough cash for this order.');return}holding.avg=(holding.shares*holding.avg+total)/(holding.shares+qty);holding.shares+=qty;market.holdings[symbol]=holding;state.balance-=total}else{if(qty>holding.shares){toast('Not enough shares to sell.');return}holding.shares-=qty;state.balance+=total;if(holding.shares)market.holdings[symbol]=holding;else delete market.holdings[symbol]}market.trades.unshift({side:dorraMarketUi.side,symbol,qty,price:Number(fill.toFixed(2)),fee:Number(fee.toFixed(2)),total,at:Date.now()});market.trades=market.trades.slice(0,40);state.history.unshift({text:`Markets: ${dorraMarketUi.side==='buy'?'Bought':'Sold'} ${qty} ${symbol} for ${dorraMarketMoney(total)}.`});dorraMarketUi.qty=1;save('market-trade');renderDorraMarketApp(true);toast(`${dorraMarketUi.side==='buy'?'Purchase':'Sale'} completed at ${dorraMarketMoney(fill)}.`)},{capture:true});

