dorraMarketUi.orderType??='market';dorraMarketUi.limitPrice??=0;bloombergUi.tab??='intelligence';bloombergUi.filter??='all';
const ensureDorraMarketV2=ensureDorraMarket;
ensureDorraMarket=function(){let market=ensureDorraMarketV2();market.orders??=[];market.realisedPnl??=0;market.events.forEach(event=>{event.status??=event.applied?'released':'scheduled'});return market};
const dorraMarketTickV2=dorraMarketTick;
dorraMarketTick=function(persist=true){let market=ensureDorraMarket(),releasing=market.events.filter(event=>!event.applied&&event.impactTick===market.tick+1);releasing.forEach(event=>event.prePrice=market.quotes[event.symbol]?.price);dorraMarketTickV2(false);releasing.forEach(event=>{let post=market.quotes[event.symbol]?.price;event.actualMove=event.prePrice?Number(((post/event.prePrice-1)*100).toFixed(2)):0;event.correct=Math.sign(event.actualMove)===event.direction;event.status='released'});market.orders.filter(order=>order.status==='open').forEach(order=>{let quote=market.quotes[order.symbol],trigger=order.side==='buy'?quote.price<=order.limit:quote.price>=order.limit;if(!trigger)return;let holding=market.holdings[order.symbol]||{shares:0,avg:0},subtotal=order.qty*order.limit,fee=Math.max(1,subtotal*.001),total=Number((order.side==='buy'?subtotal+fee:subtotal-fee).toFixed(2));if(order.side==='buy'&&state.balance>=total){holding.avg=(holding.shares*holding.avg+total)/(holding.shares+order.qty);holding.shares+=order.qty;market.holdings[order.symbol]=holding;state.balance-=total;order.status='filled'}else if(order.side==='sell'&&holding.shares>=order.qty){holding.shares-=order.qty;state.balance+=total;market.realisedPnl+=order.qty*(order.limit-holding.avg)-fee;if(holding.shares)market.holdings[order.symbol]=holding;else delete market.holdings[order.symbol];order.status='filled'}else order.status='rejected';if(order.status==='filled')market.trades.unshift({side:order.side,symbol:order.symbol,qty:order.qty,price:order.limit,fee,total,at:Date.now(),type:'limit'})});market.orders=market.orders.slice(-30);if(persist)save('market')};
function dorraPortfolioAnalytics(){let market=ensureDorraMarket(),cost=0,value=0,rows=[];Object.entries(market.holdings).forEach(([symbol,holding])=>{let quote=market.quotes[symbol],position=holding.shares*quote.price,basis=holding.shares*holding.avg,pnl=position-basis;cost+=basis;value+=position;rows.push({symbol,shares:holding.shares,avg:holding.avg,price:quote.price,value:position,pnl,pct:basis?pnl/basis*100:0})});return {cost,value,pnl:value-cost,pct:cost?(value-cost)/cost*100:0,rows:rows.sort((a,b)=>b.value-a.value)}}
function dorraPortfolioPanel(){let data=dorraPortfolioAnalytics(),market=ensureDorraMarket(),open=market.orders.filter(order=>order.status==='open');return `<section class="market-positions"><header><h3>Portfolio positions</h3><span class="${data.pnl>=0?'up':'down'}">${data.pnl>=0?'+':''}${dorraMarketMoney(data.pnl)} · ${data.pct.toFixed(2)}%</span></header>${data.rows.length?data.rows.map(row=>`<button data-market-stock="${row.symbol}"><b>${row.symbol}</b><span>${row.shares} shares · avg ${dorraMarketMoney(row.avg)}</span><strong>${dorraMarketMoney(row.value)}<small class="${row.pnl>=0?'up':'down'}">${row.pnl>=0?'+':''}${dorraMarketMoney(row.pnl)}</small></strong></button>`).join(''):'<p>No positions yet. Buy a stock to begin tracking cost basis and returns.</p>'}${open.length?`<footer><b>${open.length} open limit order${open.length===1?'':'s'}</b>${open.map(order=>`<button data-cancel-order="${order.id}"><span>${order.side.toUpperCase()} ${order.qty} ${order.symbol} @ ${dorraMarketMoney(order.limit)}</span><i>Cancel</i></button>`).join('')}</footer>`:''}</section>`}
const dorraMarketOrderSheetV2=dorraMarketOrderSheet;
dorraMarketOrderSheet=function(){let html=dorraMarketOrderSheetV2(),company=dorraMarketCompanies.find(item=>item.symbol===dorraMarketUi.selected),quote=ensureDorraMarket().quotes[company.symbol],limit=Number(dorraMarketUi.limitPrice)||quote.price;let controls=`<div class="market-order-type"><button class="${dorraMarketUi.orderType==='market'?'active':''}" data-order-type="market">Market</button><button class="${dorraMarketUi.orderType==='limit'?'active':''}" data-order-type="limit">Limit</button></div>${dorraMarketUi.orderType==='limit'?`<label class="market-limit-price"><span>Limit price<small>Order fills at this price or better</small></span><input data-limit-price type="number" min="1" step="0.01" value="${limit.toFixed(2)}"></label>`:''}`;html=html.replace('<div class="market-side">',controls+'<div class="market-side">');if(dorraMarketUi.orderType==='limit'){let holding=ensureDorraMarket().holdings[company.symbol]||{shares:0},qty=Math.max(1,Number(dorraMarketUi.qty)||1),valid=dorraMarketUi.side==='buy'?state.balance>=qty*limit:holding.shares>=qty;html=html.replace(/<button class="market-review" data-market-submit[^>]*>.*?<span>›<\/span><\/button>/,`<button class="market-review" data-limit-submit ${valid?'':'disabled'}>Place ${dorraMarketUi.side} limit · ${dorraMarketMoney(qty*limit)} <span>›</span></button>`)}return html};
const dorraOsMarketsV2=dorraOsMarkets;
dorraOsMarkets=function(){return dorraOsMarketsV2().replace('<div class="market-list-head">',`${dorraPortfolioPanel()}<div class="market-list-head">`)};
function bloombergAccuracy(){let released=ensureDorraMarket().events.filter(event=>event.applied&&Number.isFinite(event.actualMove)),correct=released.filter(event=>event.correct).length;return {released,correct,rate:released.length?correct/released.length*100:0,avg:released.length?released.reduce((sum,event)=>sum+Math.abs(event.actualMove),0)/released.length:0}}
const dorraOsBloombergV2=dorraOsBloomberg;
dorraOsBloomberg=function(){if(!dorraAppOwned('bloomberg'))return dorraOsBloombergV2();let market=ensureDorraMarket(),accuracy=bloombergAccuracy(),upcoming=market.events.filter(event=>!event.applied).sort((a,b)=>a.impactTick-b.impactTick),nav=`<nav class="bi-nav">${[['intelligence','Intelligence'],['calendar','Calendar'],['portfolio','Portfolio'],['performance','Performance']].map(([id,label])=>`<button class="${bloombergUi.tab===id?'active':''}" data-bi-tab="${id}">${label}</button>`).join('')}</nav>`;if(bloombergUi.tab==='intelligence')return dorraOsBloombergV2().replace('<div class="bi-ticker">',nav+'<div class="bi-ticker">').replace('ADVANCE + PUBLIC',`${upcoming.length} UPCOMING · ${accuracy.rate.toFixed(0)}% HIT RATE`);let ticker=dorraOsBloombergV2().match(/<header class="bi-top">[\s\S]*?<\/header><div class="bi-ticker">[\s\S]*?<\/div>/)?.[0]||'';if(bloombergUi.tab==='calendar')return `<div class="bi-shell">${ticker.replace('<div class="bi-ticker">',nav+'<div class="bi-ticker">')}<section class="bi-workspace"><header><small>EVENT CALENDAR</small><h2>Scheduled market catalysts</h2><p>Private intelligence appears here before the simulated public reaction.</p></header>${upcoming.length?upcoming.map(event=>`<article><time>T+${event.impactTick-market.tick}</time><b>${event.symbol}</b><span><strong>${event.headline}</strong><small>${event.direction>0?'Bullish':'Bearish'} estimate · ${event.confidence}% confidence · ${(event.magnitude*100).toFixed(1)}% model impact</small></span></article>`).join(''):'<div class="bi-empty">No scheduled catalysts. The intelligence desk is monitoring the market.</div>'}</section></div>`;if(bloombergUi.tab==='portfolio'){let data=dorraPortfolioAnalytics();return `<div class="bi-shell">${ticker.replace('<div class="bi-ticker">',nav+'<div class="bi-ticker">')}<section class="bi-workspace"><header><small>PORTFOLIO MONITOR</small><h2>${dorraMarketMoney(data.value)}</h2><p class="${data.pnl>=0?'up':'down'}">${data.pnl>=0?'+':''}${dorraMarketMoney(data.pnl)} unrealised · ${data.pct.toFixed(2)}%</p></header>${data.rows.length?data.rows.map(row=>`<article><b>${row.symbol}</b><span><strong>${row.shares} shares at ${dorraMarketMoney(row.avg)}</strong><small>Last ${dorraMarketMoney(row.price)} · value ${dorraMarketMoney(row.value)}</small></span><em class="${row.pnl>=0?'up':'down'}">${row.pnl>=0?'+':''}${dorraMarketMoney(row.pnl)}</em></article>`).join(''):'<div class="bi-empty">No holdings. Positions purchased in Markets will appear here.</div>'}</section></div>`}return `<div class="bi-shell">${ticker.replace('<div class="bi-ticker">',nav+'<div class="bi-ticker">')}<section class="bi-workspace"><header><small>MODEL PERFORMANCE</small><h2>${accuracy.rate.toFixed(0)}% directional accuracy</h2><p>${accuracy.correct} correct from ${accuracy.released.length} scored events · ${accuracy.avg.toFixed(2)}% average absolute move</p></header>${accuracy.released.length?accuracy.released.slice().reverse().map(event=>`<article><i class="${event.correct?'correct':'miss'}">${event.correct?'✓':'×'}</i><b>${event.symbol}</b><span><strong>${event.headline}</strong><small>Forecast ${event.direction>0?'up':'down'} ${(event.magnitude*100).toFixed(1)}% · actual ${event.actualMove>0?'+':''}${event.actualMove.toFixed(2)}%</small></span></article>`).join(''):'<div class="bi-empty">No scored events yet. Results appear after scheduled reactions occur.</div>'}</section></div>`};
const startDorraMarketClockV2=startDorraMarketClock;
startDorraMarketClock=function(){stopDorraMarketClock();let delay=dorraMarketRate().ms;if(!delay)return;dorraMarketTimer=setInterval(()=>{let title=$('#dorraOsAppTitle').textContent;if($('#dorraOs').hidden||$('#dorraOsApp').hidden||!['Markets','Bloomberg'].includes(title)){stopDorraMarketClock();return}dorraMarketTick(false);let top=$('#dorraOsAppBody').scrollTop;$('#dorraOsAppBody').innerHTML=title==='Markets'?dorraOsMarkets():dorraOsBloomberg();$('#dorraOsAppBody').scrollTop=top},delay)};
