$('#dorraOsAppBody').addEventListener('click',event=>{let type=event.target.closest('[data-order-type]'),limitSubmit=event.target.closest('[data-limit-submit]'),cancel=event.target.closest('[data-cancel-order]'),tab=event.target.closest('[data-bi-tab]');if(type){dorraMarketUi.orderType=type.dataset.orderType;if(dorraMarketUi.orderType==='limit')dorraMarketUi.limitPrice=ensureDorraMarket().quotes[dorraMarketUi.selected].price;renderDorraMarketApp(true);return}if(limitSubmit&&!limitSubmit.disabled){let market=ensureDorraMarket(),qty=Math.max(1,Math.floor(Number(dorraMarketUi.qty)||1)),limit=Math.max(1,Number(dorraMarketUi.limitPrice)||market.quotes[dorraMarketUi.selected].price);market.orders.push({id:`order-${Date.now()}`,symbol:dorraMarketUi.selected,side:dorraMarketUi.side,qty,limit:Number(limit.toFixed(2)),status:'open',placedTick:market.tick,at:Date.now()});save('limit-order');renderDorraMarketApp(true);toast('Limit order placed.');return}if(cancel){let order=ensureDorraMarket().orders.find(item=>item.id===cancel.dataset.cancelOrder);if(order&&order.status==='open')order.status='cancelled';save('cancel-order');renderDorraMarketApp(true);return}if(tab){bloombergUi.tab=tab.dataset.biTab;openDorraOsApp('bloomberg')}});
$('#dorraOsAppBody').addEventListener('change',event=>{if(event.target.matches('[data-limit-price]')){dorraMarketUi.limitPrice=Math.max(1,Number(event.target.value)||1);renderDorraMarketApp(true)}});

// Markets Pro 3.0: workstation navigation, advanced orders, risk and Bloomberg research hand-off.
Object.assign(dorraMarketUi,{tab:dorraMarketUi.tab||'watchlist',range:dorraMarketUi.range||'1D',search:dorraMarketUi.search||'',sort:dorraMarketUi.sort||'symbol',timeInForce:dorraMarketUi.timeInForce||'day',stopPrice:dorraMarketUi.stopPrice||0});
function marketSession(){let step=ensureDorraMarket().tick%36;if(step<5)return {id:'pre',label:'Pre-market',detail:'Limited liquidity'};if(step<30)return {id:'regular',label:'Market open',detail:`Closes in ${30-step} ticks`};return {id:'after',label:'After hours',detail:'Wider spreads'}}
function marketReservations(){let cash=0,shares={};ensureDorraMarket().orders.filter(order=>order.status==='open').forEach(order=>{if(order.side==='buy')cash+=order.qty*(order.limit||order.stop||ensureDorraMarket().quotes[order.symbol].price)*1.001;else shares[order.symbol]=(shares[order.symbol]||0)+order.qty});return {cash,shares}}
function marketLinePath(values,width=420,height=120){if(!values.length)return '';let min=Math.min(...values),max=Math.max(...values),span=max-min||1;return values.map((value,index)=>`${index?'L':'M'}${(index/(values.length-1||1)*width).toFixed(1)} ${(height-(value-min)/span*(height-12)-6).toFixed(1)}`).join(' ')}
function marketStockChart(){let market=ensureDorraMarket(),company=dorraMarketCompanies.find(item=>item.symbol===dorraMarketUi.selected)||dorraMarketCompanies[0],quote=market.quotes[company.symbol],counts={'1D':12,'1W':24,'1M':36,ALL:48},values=quote.history.slice(-counts[dorraMarketUi.range]),first=values[0]||quote.price,change=(quote.price-first)/first*100,spread=marketSpread(company)*(marketSession().id==='regular'?1:1.7);return `<section class="market-detail"><header><div><small>${company.sector} · ${company.symbol}</small><h2>${company.name}</h2></div><div><strong>${dorraMarketMoney(quote.price)}</strong><small class="${change>=0?'up':'down'}">${change>=0?'+':''}${change.toFixed(2)}% ${dorraMarketUi.range}</small></div></header><div class="market-quote-strip"><span>Bid <b>${(quote.price-spread/2).toFixed(2)}</b></span><span>Ask <b>${(quote.price+spread/2).toFixed(2)}</b></span><span>Previous <b>${quote.prevClose.toFixed(2)}</b></span><span>Volume <b>${(quote.volume/1000).toFixed(0)}K</b></span></div><div class="market-ranges">${Object.keys(counts).map(range=>`<button class="${dorraMarketUi.range===range?'active':''}" data-market-range="${range}">${range}</button>`).join('')}</div><svg class="market-stock-chart" viewBox="0 0 420 150" preserveAspectRatio="none"><path class="market-chart-grid" d="M0 35H420M0 75H420M0 115H420"/><path class="market-chart-fill" d="${marketLinePath(values)} L420 150 L0 150Z"/><path class="market-chart-price" d="${marketLinePath(values)}"/>${values.map((value,index)=>{let h=8+Math.abs(value-(values[index-1]||value))/quote.price*500;return `<path class="market-volume-bar" d="M${(index/(values.length-1||1)*420).toFixed(1)} 150V${Math.max(122,150-h).toFixed(1)}"/>`}).join('')}</svg><footer><button data-open-bloomberg-stock="${company.symbol}">Open ${company.symbol} in Bloomberg ↗</button><small>Research and full fundamentals are exclusive to Bloomberg.</small></footer></section>`}
function marketRiskPanel(){let data=dorraPortfolioAnalytics(),market=ensureDorraMarket(),total=data.value||1,largest=data.rows[0]?.value||0,concentration=largest/total*100,vol=data.rows.reduce((sum,row)=>{let company=dorraMarketCompanies.find(item=>item.symbol===row.symbol);return sum+row.value/total*company.volatility*100},0),beta=data.rows.reduce((sum,row)=>{let company=dorraMarketCompanies.find(item=>item.symbol===row.symbol);return sum+row.value/total*company.beta},0),stress=data.value*(vol/100)*-2.4;return `<section class="market-risk"><header><small>PORTFOLIO RISK</small><h2>${data.rows.length?(concentration>55?'High concentration':'Measured exposure'):'No exposure yet'}</h2></header><div><span>Weighted volatility<b>${vol.toFixed(1)}%</b></span><span>Portfolio beta<b>${beta.toFixed(2)}</b></span><span>Largest position<b>${concentration.toFixed(0)}%</b></span><span>Stress scenario<b class="down">${dorraMarketMoney(stress)}</b></span></div><p>Stress estimate models a broad two-volatility market decline. It is a simulation, not a forecast.</p></section>`}
function marketOrdersPanel(){let orders=ensureDorraMarket().orders.slice().reverse();return `<section class="market-orders-view"><header><small>ORDER LIFECYCLE</small><h2>Orders</h2></header>${orders.length?orders.map(order=>`<article><i class="${order.status}"></i><span><strong>${order.side.toUpperCase()} ${order.qty} ${order.symbol}</strong><small>${(order.type||'limit').replace('-',' ')} · ${order.tif?.toUpperCase()||'GTC'} · ${order.limit?dorraMarketMoney(order.limit):''}${order.stop?` trigger ${dorraMarketMoney(order.stop)}`:''}</small></span><b>${order.status}</b>${order.status==='open'?`<button data-cancel-order="${order.id}">Cancel</button>`:''}</article>`).join(''):'<div class="market-empty">No orders placed yet.</div>'}</section>`}
function marketNewsPanel(){let events=ensureDorraMarket().events.slice().reverse();return `<section class="market-orders-view"><header><small>PUBLIC TAPE</small><h2>Market news</h2></header>${events.length?events.map(event=>`<article><i class="${event.applied?'filled':'open'}"></i><span><strong>${event.applied?event.headline:`${event.symbol}: catalyst pending`}</strong><small>${event.applied?'Public · price reaction recorded':'Details available early in Bloomberg'}</small></span><b>${event.applied?'public':'pending'}</b></article>`).join(''):'<div class="market-empty">No public stories yet.</div>'}</section>`}
function marketPortfolioView(){let data=dorraPortfolioAnalytics(),market=ensureDorraMarket(),fees=market.trades.reduce((sum,trade)=>sum+(trade.fee||0),0),total=state.balance+data.value;return `<section class="market-account"><header><small>NET LIQUIDATION VALUE</small><h2>${dorraMarketMoney(total)}</h2><p class="${data.pnl+market.realisedPnl>=0?'up':'down'}">${data.pnl+market.realisedPnl>=0?'+':''}${dorraMarketMoney(data.pnl+market.realisedPnl)} total P&amp;L</p></header><div class="market-account-metrics"><span>Unrealised<b>${dorraMarketMoney(data.pnl)}</b></span><span>Realised<b>${dorraMarketMoney(market.realisedPnl)}</b></span><span>Fees paid<b>${dorraMarketMoney(fees)}</b></span><span>Cash<b>${dorraMarketMoney(state.balance)}</b></span></div>${dorraPortfolioPanel()}<div class="market-allocation">${data.rows.map(row=>`<span style="--share:${(row.value/(data.value||1)*100).toFixed(1)}%"><b>${row.symbol}</b><i></i><em>${(row.value/(data.value||1)*100).toFixed(1)}%</em></span>`).join('')||'<p>No allocation to display.</p>'}</div></section>`}
const dorraMarketOrderSheetV3=dorraMarketOrderSheet;
dorraMarketOrderSheet=function(){let market=ensureDorraMarket(),company=dorraMarketCompanies.find(item=>item.symbol===dorraMarketUi.selected),quote=market.quotes[company.symbol],holding=market.holdings[company.symbol]||{shares:0},reserve=marketReservations(),qty=Math.max(1,Number(dorraMarketUi.qty)||1),limit=Number(dorraMarketUi.limitPrice)||quote.price,stop=Number(dorraMarketUi.stopPrice)||quote.price,type=dorraMarketUi.orderType,advanced=type!=='market',reference=type==='stop'?stop:limit,availableCash=state.balance-reserve.cash,availableShares=holding.shares-(reserve.shares[company.symbol]||0),valid=dorraMarketUi.side==='buy'?availableCash>=qty*reference*1.001:availableShares>=qty;return `<section class="market-order market-order-pro"><header><div><strong>${company.symbol}</strong><small>${marketSession().label} · ${holding.shares} owned</small></div><b>${dorraMarketMoney(quote.price)}<small>${dorraMarketMoney(availableCash)} available</small></b><button data-market-close>×</button></header><div class="market-side"><button class="${dorraMarketUi.side==='buy'?'active':''}" data-market-side="buy">Buy</button><button class="${dorraMarketUi.side==='sell'?'active':''}" data-market-side="sell">Sell</button></div><label class="market-select"><span>Order type</span><select data-advanced-type><option value="market" ${type==='market'?'selected':''}>Market</option><option value="limit" ${type==='limit'?'selected':''}>Limit</option><option value="stop" ${type==='stop'?'selected':''}>Stop</option><option value="stop-limit" ${type==='stop-limit'?'selected':''}>Stop limit</option><option value="take-profit" ${type==='take-profit'?'selected':''}>Take profit</option></select></label>${['limit','stop-limit','take-profit'].includes(type)?`<label class="market-limit-price"><span>${type==='take-profit'?'Target':'Limit'} price<small>Execution price or better</small></span><input data-limit-price type="number" min="1" step="0.01" value="${limit.toFixed(2)}"></label>`:''}${['stop','stop-limit'].includes(type)?`<label class="market-limit-price"><span>Stop trigger<small>Activates when crossed</small></span><input data-stop-price type="number" min="1" step="0.01" value="${stop.toFixed(2)}"></label>`:''}<div class="market-qty"><span>Shares</span><div><button data-market-qty="-1">−</button><input data-market-input inputmode="numeric" value="${qty}"><button data-market-qty="1">+</button></div></div>${advanced?`<label class="market-select"><span>Time in force</span><select data-market-tif><option value="day" ${dorraMarketUi.timeInForce==='day'?'selected':''}>Day</option><option value="gtc" ${dorraMarketUi.timeInForce==='gtc'?'selected':''}>Good till cancelled</option></select></label>`:''}<button class="market-review" ${type==='market'?'data-market-submit':'data-advanced-submit'} ${valid?'':'disabled'}>${valid?(type==='market'?'Review market order':`Place ${type.replace('-',' ')} order`):(dorraMarketUi.side==='buy'?'Insufficient available cash':'Shares reserved or unavailable')} <span>›</span></button><small class="market-disclaimer">${advanced?'Funds or shares are reserved while open.':'Spread and 0.10% fee included. Costs round up; proceeds round down to whole dollars.'} · Simulated trading</small></section>`};
const dorraMarketTickV3=dorraMarketTick;
dorraMarketTick=function(persist=true){let market=ensureDorraMarket(),startTick=market.tick;dorraMarketTickV3(false);market.events.forEach((event,index)=>{event.category??=['Earnings','Macro','Regulation','Contract'][index%4];event.sourceStatus??=event.applied?'public':index%3?'confirmed':'rumour'});market.orders.filter(order=>order.status==='open'&&!['limit'].includes(order.type||'limit')).forEach(order=>{let quote=market.quotes[order.symbol],stopCross=order.side==='buy'?quote.price>=order.stop:quote.price<=order.stop,targetCross=order.side==='buy'?quote.price<=order.limit:quote.price>=order.limit,trigger=order.type==='take-profit'?targetCross:order.type==='stop-limit'?(order.triggered||stopCross)&&targetCross:stopCross;if(order.type==='stop-limit'&&stopCross)order.triggered=true;if(!trigger)return;let company=dorraMarketCompanies.find(item=>item.symbol===order.symbol),holding=market.holdings[order.symbol]||{shares:0,avg:0},fill=order.limit||quote.price+(order.side==='buy'?marketSpread(company)/2:-marketSpread(company)/2),fee=Math.max(1,order.qty*fill*.001),total=Number((order.side==='buy'?order.qty*fill+fee:order.qty*fill-fee).toFixed(2));if(order.side==='buy'&&state.balance>=total){holding.avg=(holding.shares*holding.avg+total)/(holding.shares+order.qty);holding.shares+=order.qty;market.holdings[order.symbol]=holding;state.balance-=total;order.status='filled'}else if(order.side==='sell'&&holding.shares>=order.qty){holding.shares-=order.qty;state.balance+=total;market.realisedPnl+=order.qty*(fill-holding.avg)-fee;if(holding.shares)market.holdings[order.symbol]=holding;else delete market.holdings[order.symbol];order.status='filled'}else order.status='rejected';if(order.status==='filled')market.trades.unshift({side:order.side,symbol:order.symbol,qty:order.qty,price:fill,fee,total,at:Date.now(),type:order.type})});if((startTick%36)<30&&market.tick%36>=30)market.orders.filter(order=>order.status==='open'&&order.tif==='day').forEach(order=>order.status='expired');if(persist)save('market')};
const dorraOsMarketsV3=dorraOsMarkets;
dorraOsMarkets=function(){let market=ensureDorraMarket(),session=marketSession(),reservations=marketReservations(),index=dorraMarketIndex(),filtered=dorraMarketCompanies.filter(company=>(company.symbol+' '+company.name).toLowerCase().includes(dorraMarketUi.search.toLowerCase())).sort((a,b)=>dorraMarketUi.sort==='change'?((market.quotes[b.symbol].price-market.quotes[b.symbol].open)/market.quotes[b.symbol].open)-((market.quotes[a.symbol].price-market.quotes[a.symbol].open)/market.quotes[a.symbol].open):a.symbol.localeCompare(b.symbol));let content=dorraMarketUi.tab==='portfolio'?marketPortfolioView():dorraMarketUi.tab==='orders'?marketOrdersPanel():dorraMarketUi.tab==='news'?marketNewsPanel():dorraMarketUi.tab==='risk'?marketRiskPanel():`<div class="market-workstation"><aside><div class="market-search"><input data-market-search placeholder="Search symbols" value="${osEscape(dorraMarketUi.search)}"><button data-market-sort="${dorraMarketUi.sort==='symbol'?'change':'symbol'}">${dorraMarketUi.sort==='symbol'?'A–Z':'% change'}</button></div><div class="market-watch">${filtered.map(company=>{let q=market.quotes[company.symbol],pct=(q.price-q.open)/q.open*100;return `<button class="market-row ${dorraMarketUi.selected===company.symbol?'selected':''}" data-market-stock="${company.symbol}"><span><strong>${company.symbol}</strong><small>${company.name}</small></span><b>${q.price.toFixed(2)}</b><em class="${pct>=0?'up':'down'}">${pct>=0?'+':''}${pct.toFixed(2)}%</em></button>`}).join('')}</div></aside><main>${marketStockChart()}</main><aside>${dorraMarketUi.selected?dorraMarketOrderSheet():''}</aside></div>`;return `<div class="markets-shell markets-pro"><header class="market-pro-head"><div><small>DORRA MARKETS PRO</small><strong>${index.current.toFixed(2)} <em class="${index.change>=0?'up':'down'}">${index.change>=0?'+':''}${index.pct.toFixed(2)}%</em></strong></div><span class="${session.id}"><i></i>${session.label}<small>${session.detail}</small></span><button data-market-tick>↻ Tick</button></header><nav class="market-pro-nav">${[['watchlist','Watchlist'],['portfolio','Portfolio'],['orders','Orders'],['news','News'],['risk','Risk']].map(([id,label])=>`<button class="${dorraMarketUi.tab===id?'active':''}" data-market-tab="${id}">${label}${id==='orders'&&market.orders.filter(order=>order.status==='open').length?` <b>${market.orders.filter(order=>order.status==='open').length}</b>`:''}</button>`).join('')}</nav><div class="market-buying-power"><span>Buying power <b>${dorraMarketMoney(Math.max(0,state.balance-reservations.cash))}</b></span><span>Reserved <b>${dorraMarketMoney(reservations.cash)}</b></span><span>Regime <b>${market.regime.name}</b></span></div>${content}</div>`};
const dorraOsBloombergV3=dorraOsBloomberg;
dorraOsBloomberg=function(){if(!dorraAppOwned('bloomberg'))return dorraOsBloombergV3();let navItems=[['intelligence','Intelligence'],['calendar','Calendar'],['research','Research'],['portfolio','Portfolio'],['performance','Performance']];if(bloombergUi.tab!=='research')return dorraOsBloombergV3().replace(/<nav class="bi-nav">[\s\S]*?<\/nav>/,`<nav class="bi-nav">${navItems.map(([id,label])=>`<button class="${bloombergUi.tab===id?'active':''}" data-bi-tab="${id}">${label}</button>`).join('')}</nav>`);let market=ensureDorraMarket(),symbol=bloombergUi.researchSymbol||dorraMarketUi.selected||dorraMarketCompanies[0].symbol,company=dorraMarketCompanies.find(item=>item.symbol===symbol),quote=market.quotes[symbol],growth=((company.drift||.0002)*250*100),margin=10+company.beta*7;return `<div class="bi-shell"><header class="bi-top"><b>BI</b><div><strong>Bloomberg Intelligence</strong><small>Company research · simulated data</small></div><span><i></i> CONNECTED</span></header><nav class="bi-nav">${navItems.map(([id,label])=>`<button class="${bloombergUi.tab===id?'active':''}" data-bi-tab="${id}">${label}</button>`).join('')}</nav><section class="bi-research"><header><label>Company<select data-bi-company>${dorraMarketCompanies.map(item=>`<option value="${item.symbol}" ${item.symbol===symbol?'selected':''}>${item.symbol} · ${item.name}</option>`).join('')}</select></label><small>FULL RESEARCH · BLOOMBERG EXCLUSIVE</small><h2>${company.name}</h2><p>${company.sector} · ${symbol} · Simulated equity research profile</p></header><div class="bi-research-grid"><article><small>Investment snapshot</small><strong>${dorraMarketMoney(quote.price)}</strong><p>Price range ${dorraMarketMoney(quote.low)}–${dorraMarketMoney(quote.high)} · ${(quote.volume/1000).toFixed(0)}K volume</p></article><article><small>Valuation</small><strong>${company.pe.toFixed(1)}× P/E</strong><p>${company.yield.toFixed(1)}% simulated dividend yield</p></article><article><small>Operating profile</small><strong>${growth.toFixed(1)}% growth</strong><p>${margin.toFixed(1)}% model operating margin</p></article><article><small>Risk profile</small><strong>${company.beta.toFixed(2)} beta</strong><p>${(company.volatility*100).toFixed(1)}% base volatility coefficient</p></article></div><article class="bi-thesis"><h3>Research view</h3><p>${company.name} is modelled as a ${company.beta>1?'higher-beta':'defensive'} ${company.sector.toLowerCase()} business. Its simulated valuation, earnings sensitivity and catalyst history are presented here so Markets Pro can stay focused on execution and portfolio management.</p></article></section></div>`};
