$('#dorraOsAppBody').addEventListener('click',event=>{if($('#dorraOsAppTitle').textContent!=='Markets Pro')return;let stock=event.target.closest('[data-market-stock]'),side=event.target.closest('[data-market-side]'),qtyButton=event.target.closest('[data-market-qty]'),close=event.target.closest('[data-market-close]'),tick=event.target.closest('[data-market-tick]'),submit=event.target.closest('[data-market-submit]');if(stock){dorraMarketUi.selected=stock.dataset.marketStock;dorraMarketUi.qty=1;renderDorraMarketApp(true);return}if(side){dorraMarketUi.side=side.dataset.marketSide;renderDorraMarketApp(true);return}if(qtyButton){dorraMarketUi.qty=Math.max(1,Math.min(999,Number(dorraMarketUi.qty)+Number(qtyButton.dataset.marketQty)));renderDorraMarketApp(true);return}if(close){dorraMarketUi.selected=dorraMarketCompanies[0].symbol;renderDorraMarketApp(true);return}if(tick){dorraMarketTick();renderDorraMarketApp(true);return}if(submit&&!submit.disabled){let market=ensureDorraMarket(),symbol=dorraMarketUi.selected,company=dorraMarketCompanies.find(item=>item.symbol===symbol),quote=market.quotes[symbol],qty=Math.max(1,Math.floor(Number(dorraMarketUi.qty)||1)),fill=quote.price+(dorraMarketUi.side==='buy'?marketSpread(company)/2:-marketSpread(company)/2),subtotal=qty*fill,fee=Math.max(1,subtotal*.001),total=Number((dorraMarketUi.side==='buy'?subtotal+fee:subtotal-fee).toFixed(2)),holding=market.holdings[symbol]||{shares:0,avg:0};if(dorraMarketUi.side==='buy'){if(total>state.balance)return;holding.avg=(holding.shares*holding.avg+total)/(holding.shares+qty);holding.shares+=qty;market.holdings[symbol]=holding;state.balance-=total}else{if(qty>holding.shares)return;holding.shares-=qty;state.balance+=total;market.realisedPnl+=qty*(fill-holding.avg)-fee;if(holding.shares)market.holdings[symbol]=holding;else delete market.holdings[symbol]}market.trades.unshift({side:dorraMarketUi.side,symbol,qty,price:Number(fill.toFixed(2)),fee:Number(fee.toFixed(2)),total,at:Date.now(),type:'market'});save('market-trade');dorraMarketUi.qty=1;renderDorraMarketApp(true);toast(`Market order filled at ${dorraMarketMoney(fill)}.`)}});
const startDorraMarketClockV3=startDorraMarketClock;
