function profilePictureData(file){return new Promise((resolve,reject)=>{if(!file?.type.match(/^image\/(jpeg|png|webp)$/)){reject(new Error('Choose a JPG, PNG, or WebP image.'));return}if(file.size>10*1024*1024){reject(new Error('Choose an image smaller than 10 MB.'));return}let reader=new FileReader();reader.onerror=()=>reject(new Error('That image could not be read.'));reader.onload=()=>{let image=new Image();image.onerror=()=>reject(new Error('That image could not be opened.'));image.onload=()=>{let size=Math.min(512,image.naturalWidth,image.naturalHeight),canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;let context=canvas.getContext('2d'),source=Math.min(image.naturalWidth,image.naturalHeight),sx=(image.naturalWidth-source)/2,sy=(image.naturalHeight-source)/2;context.drawImage(image,sx,sy,source,source,0,0,size,size);resolve(canvas.toDataURL('image/jpeg',.86))};image.src=reader.result};reader.readAsDataURL(file)})}
