function empireVenueRequirements(venue,p=state.progress){let requirements=[];if(venue.stars)requirements.push({id:'stars',met:empireStars(p)>=venue.stars,label:`Reach ${venue.stars} Empire stars`,route:'empire'});if(venue.vehicle)requirements.push({id:'vehicle',met:progressionVehicles()>0,label:'Own a vehicle',route:'motor'});return requirements}
