function venueHourlyRate(venue,entry,level=entry?.level||0){if(!level)return 0;let focus=EMPIRE_FOCUSES.find(item=>item.id===(entry?.focus||'balanced'))||EMPIRE_FOCUSES[0];return Math.floor(venue.rates[level-1]*(entry?.manager?1.12:1)*focus.rate)}
function empireVenueStatus(venue,p=state.progress){let entry=p.empire.venues[venue.id],level=entry?.level||0,unlocked=venueUnlocked(p,venue,progressionVehicles());return level?'operating':unlocked?'available':'locked'}
