function empireNextMove(p,claimable){let empire=p.empire,cap=empireCapHours(p),used=(empire.unclaimedMs||0)/3600000,opening=EMPIRE_VENUES.find(venue=>empireVenueStatus(venue,p)==='available'&&state.balance>=venue.costs[0]);if(opening){let founder=opening.id==='terrace'&&p.arrival?.ownerOpeningUnlocked&&!empire.venues.terrace;return {type:'upgrade',venue:opening,eyebrow:'Next move',title:`Open ${opening.name}`,copy:`${founder?"Your Founder's Advance":"Your capital"} covers the opening. It starts earning ${formatProgressMoney(opening.rates[0])} per hour.`,button:`Open venue · ${formatProgressMoney(opening.costs[0])}`}}if(claimable>=1&&empire.openingAdvance&&empire.lifetimeEarned<100)return {type:'claim',eyebrow:'Opening income ready',title:'Bank the first house earnings',copy:'Collect the opening advance to put the new venue on the ledger.',button:`Collect ${formatProgressMoney(claimable)}`};if(claimable>=1&&used/cap>=.75)return {type:'claim',eyebrow:'Income bank filling',title:'Collect venue income',copy:`The offline bank is ${Math.round(used/cap*100)}% full. Collect now to keep every venue earning.`,button:`Collect ${formatProgressMoney(claimable)}`};let director=EMPIRE_VENUES.find(venue=>{let entry=empire.venues[venue.id];return entry?.level>=2&&!entry.manager&&state.balance>=managerCost(venue)});if(director)return {type:'manager',venue:director,eyebrow:'Management opportunity',title:`Appoint ${EMPIRE_MANAGERS[director.id].name}`,copy:`A director adds 12% output to ${director.name} and unlocks operating strategies.`,button:`Appoint director · ${formatProgressMoney(managerCost(director))}`};let upgrade=EMPIRE_VENUES.find(venue=>{let level=empire.venues[venue.id]?.level||0;return level>0&&level<5&&venueUnlocked(p,venue,progressionVehicles())&&state.balance>=venue.costs[level]});if(upgrade){let entry=empire.venues[upgrade.id],gain=venueHourlyRate(upgrade,entry,entry.level+1)-venueHourlyRate(upgrade,entry);return {type:'upgrade',venue:upgrade,eyebrow:'Best available investment',title:`Upgrade ${upgrade.name}`,copy:`The next level adds ${formatProgressMoney(gain)} per hour and advances the estate by one star.`,button:`Upgrade · ${formatProgressMoney(upgrade.costs[entry.level])}`}}if(claimable>=1)return {type:'claim',eyebrow:'Income ready',title:'Collect venue income',copy:'Move the current earnings into available capital for your next investment.',button:`Collect ${formatProgressMoney(claimable)}`};let funding=EMPIRE_VENUES.filter(venue=>{let entry=empire.venues[venue.id],level=entry?.level||0;return level<5&&venueUnlocked(p,venue,progressionVehicles())}).sort((a,b)=>a.costs[p.empire.venues[a.id]?.level||0]-b.costs[p.empire.venues[b.id]?.level||0])[0];if(funding){let level=empire.venues[funding.id]?.level||0,cost=funding.costs[level],shortfall=Math.max(0,cost-state.balance);return {type:'dashboard',venue:funding,eyebrow:'Build investment capital',title:`${level?'Upgrade':'Open'} ${funding.name}`,copy:`Earn ${formatProgressMoney(shortfall)} more at the tables or through contracts to fund the next level.`,button:'Return to house'}}let locked=EMPIRE_VENUES.find(venue=>empireVenueStatus(venue,p)==='locked'),requirement=locked&&empireVenueRequirements(locked,p).find(item=>!item.met);return locked?{type:requirement?.route||'empire',venue:locked,eyebrow:'Next estate unlock',title:locked.name,copy:`${requirement?.label||'Keep developing the estate'}. House Empire progression controls every venue unlock.`,button:requirement?.route==='motor'?'Visit Motor Gallery':'Review Empire requirements'}:{type:'office',eyebrow:'Estate complete',title:'Dorra House is fully restored',copy:'Review the permanent record of your investments, directors, and house-wide advantages.',button:'Open Office Ledger'}}
function renderEmpireVenueRow(venue,p){let entry=p.empire.venues[venue.id],level=entry?.level||0,status=empireVenueStatus(venue,p),rate=venueHourlyRate(venue,entry),selected=venue.id===empireSelectedVenue,unmet=empireVenueRequirements(venue,p).filter(item=>!item.met).map(item=>item.label).join(' · ');return `<button type="button" class="empire-card empire-venue-row ${status} ${selected?'selected':''}" data-venue-select="${venue.id}" role="option" aria-selected="${selected}"><span class="empire-venue-icon" aria-hidden="true">${venue.icon}</span><span class="empire-venue-copy"><strong>${venue.name}</strong><small>${status==='operating'?`${venue.levels[level-1]} · Level ${level}`:status==='available'?'Ready to open':unmet}</small></span><span class="empire-venue-output"><b>${level?`Level ${level}`:'Level 0'}</b><small>${formatProgressMoney(rate)} / h</small></span><i aria-hidden="true">›</i></button>`}
function renderEmpireRequirements(venue,p){let requirements=empireVenueRequirements(venue,p);return `<div class="empire-requirements" aria-label="Venue requirements">${requirements.map(item=>`<div class="${item.met?'met':'unmet'}"><span aria-hidden="true">${item.met?'✓':'○'}</span><strong>${item.label}</strong></div>`).join('')}</div>`}
function renderEmpireDetail(venue,p){let empire=p.empire,entry=empire.venues[venue.id]||{level:0,manager:false,focus:'balanced'},level=entry.level||0,unlocked=venueUnlocked(p,venue,progressionVehicles()),status=level?'Operating':unlocked?'Ready to open':'Locked',currentRate=venueHourlyRate(venue,entry),nextLevel=Math.min(5,level+1),nextRate=level<5?venueHourlyRate(venue,entry,nextLevel):currentRate,gain=Math.max(0,nextRate-currentRate),cost=level<5?venue.costs[level]:0,shortfall=Math.max(0,cost-state.balance),signature=VENUE_SIGNATURE_PERKS[venue.id],manager=EMPIRE_MANAGERS[venue.id],art=EMPIRE_ART[venue.id],contractLocked=!!p.contracts.activeId,bankRate=(level<5?nextRate:currentRate)*empireCapHours(p),management='';if(level<2)management=`<section class="empire-director future"><header><span><small>Future director</small><strong>${manager.name}</strong><em>${manager.title}</em></span><b>Available at Level 2</b></header><p>Appointment cost ${formatProgressMoney(managerCost(venue))} · adds 12% base output and unlocks strategy control.</p></section>`;else if(!entry.manager)management=`<section class="empire-director ready"><header><span><small>Director position ready</small><strong>${manager.name}</strong><em>${manager.title} · +12% base output</em></span><b>${formatProgressMoney(managerCost(venue))}</b></header><button data-venue-manager="${venue.id}" ${state.balance<managerCost(venue)?'disabled':''}>Appoint director</button>${state.balance<managerCost(venue)?`<p>Need ${formatProgressMoney(managerCost(venue)-state.balance)} more.</p>`:''}</section>`;else management=`<section class="empire-director appointed"><header><span><small>Appointed director</small><strong>${manager.name}</strong><em>${manager.title} · +12% base output</em></span><b>On duty</b></header></section>`;let strategies=`<section class="empire-strategy"><header><div><small>Operating strategy</small><strong>${entry.manager?'Set the venue directive':'A director is required to choose a strategy'}</strong></div>${contractLocked&&entry.manager?'<span>Locked while a VIP brief is active</span>':''}</header><div>${EMPIRE_FOCUSES.map(focus=>{let active=(entry.focus||'balanced')===focus.id,disabled=!entry.manager||contractLocked;return `<button class="${active?'active':''}" data-venue-focus="${venue.id}" data-focus="${focus.id}" aria-pressed="${active}" ${disabled?'disabled':''}><strong>${focus.name}</strong><small>${focus.copy}</small></button>`}).join('')}</div></section>`;let action=unlocked?(level<5?`<div class="empire-detail-action"><span><small>${level?'Next investment':'Opening investment'}</small><strong>${formatProgressMoney(cost)}</strong>${shortfall?`<em>Need ${formatProgressMoney(shortfall)} more</em>`:'<em>Available now</em>'}</span><button data-venue-upgrade="${venue.id}" ${shortfall?'disabled':''}>${level?`Upgrade to Level ${level+1}`:`Open ${venue.name}`} · ${formatProgressMoney(cost)}</button></div>`:`<div class="empire-detail-action complete"><span><small>Venue status</small><strong>Fully upgraded</strong><em>All five estate stars earned</em></span><button disabled>Iconic venue</button></div>`):`<div class="empire-detail-action locked"><div><small>Before this venue can open</small>${renderEmpireRequirements(venue,p)}</div><button data-empire-route="${empireVenueRequirements(venue,p).find(item=>!item.met)?.route||'empire'}">Review next requirement</button></div>`;return `<article class="empire-operations ${unlocked?'':'locked'}" aria-labelledby="empireVenueTitle"><header class="empire-operations-head"><div class="empire-venue-title"><span aria-hidden="true">${venue.icon}</span><div><small>${venue.area}</small><h2 id="empireVenueTitle" tabindex="-1">${venue.name}</h2><p>${venue.copy}</p><b class="empire-status ${status.toLowerCase().replaceAll(' ','-')}">${status}</b><em>Level ${level} / 5</em></div></div><div class="empire-venue-art"><img src="${art.src}" alt="${art.alt}" loading="lazy" decoding="async"><span>${venue.area}</span></div></header><section class="empire-levels" aria-label="${venue.name} level progression"><header><small>Level progression</small><strong>${level?venue.levels[level-1]:'Not yet operating'}</strong></header><ol>${venue.levels.map((name,index)=>{let step=index+1;return `<li class="${step<=level?'complete':step===level+1?'next':''}"><i aria-hidden="true">${step<=level?'✓':step}</i><span>${name}</span></li>`}).join('')}</ol><div class="venue-track" role="progressbar" aria-label="Venue level" aria-valuemin="0" aria-valuemax="5" aria-valuenow="${level}"><i style="width:${level*20}%"></i></div></section><section class="empire-projection"><div><small>${level?'Current output':'Opening cost'}</small><strong>${level?`${formatProgressMoney(currentRate)} / hour`:formatProgressMoney(cost)}</strong><span>${level?`${formatProgressMoney(currentRate*empireCapHours(p))} per full bank`:'One level earns one Empire star'}</span></div><div><small>${level<5?'Next-level output':'Current output'}</small><strong>${formatProgressMoney(level<5?nextRate:currentRate)} / hour</strong><span>${level<5?`+${formatProgressMoney(gain)} per hour`:'Maximum venue output'}</span></div><div><small>${empireCapHours(p)}-hour bank</small><strong>${formatProgressMoney(bankRate)}</strong><span>${level<5?'Projected after next investment':'At the current strategy'}</span></div></section><div class="empire-operations-grid"><section class="empire-signature ${level>=3?'active':''}"><small>${level>=3?'Signature perk active':'Signature perk at Level 3'}</small><strong>${signature.name}</strong><p>${signature.copy}</p></section>${management}</div>${strategies}${action}</article>`}
function empireEventHTML(p){let event=EMPIRE_EVENTS.find(item=>item.id===p.empire.event?.id);if(!event)return '';return `<section class="business-event"><header><div><small>Decision required · Week ${p.empire.week}</small><h3>${event.name}</h3></div><b>Trading paused</b></header><p>${event.copy}</p><div>${event.choices.map(choice=>`<button data-business-event-choice="${choice.id}" ${state.balance<(choice.cost||0)?'disabled':''}><strong>${choice.label}</strong><span>${choice.copy}</span><small>${choice.cost?formatProgressMoney(choice.cost):'No capital cost'}</small></button>`).join('')}</div></section>`}
function empireOverviewHTML(p,snapshot){let history=p.empire.businessHistory,max=Math.max(1,...history.map(item=>Math.max(item.gross,item.expenses))),segments=EMPIRE_CUSTOMER_SEGMENTS.map(segment=>{let value=snapshot.segmentDemand[segment.id]||1;return `<article><span><strong>${segment.name}</strong><small>${segment.copy}</small></span><b>${Math.round(value*100)}%</b><i><em style="width:${Math.min(100,value*75)}%"></em></i></article>`}).join(''),competitors=p.empire.competitors.map(item=>`<article><span><strong>${item.name}</strong><small>${item.trend>0?'Growing':item.trend<0?'Contracting':'Holding'} this week</small></span><b>${item.score}</b></article>`).join('');return `${empireEventHTML(p)}<div class="business-kpis"><article><small>Gross revenue</small><strong>${formatProgressMoney(snapshot.gross)}<em>/h</em></strong><span>${formatProgressMoney(snapshot.weekly.gross)} projected weekly</span></article><article><small>Operating expenses</small><strong>${formatProgressMoney(snapshot.expenses)}<em>/h</em></strong><span>${snapshot.gross?Math.round(snapshot.expenses/snapshot.gross*100):0}% cost ratio</span></article><article class="${snapshot.net<0?'negative':''}"><small>Net profit</small><strong>${snapshot.net<0?'−':''}${formatProgressMoney(Math.abs(snapshot.net))}<em>/h</em></strong><span>${formatProgressMoney(snapshot.weekly.net)} projected weekly</span></article><article><small>Guest satisfaction</small><strong>${snapshot.satisfaction}%</strong><span>${snapshot.utilisation}% estate utilisation</span></article><article><small>Market share</small><strong>${snapshot.marketShare}%</strong><span>${p.empire.reputation}/100 reputation</span></article></div><div class="business-overview-grid"><section class="business-card"><header><small>Demand mix</small><h3>Customer segments</h3></header><div class="business-segments">${segments}</div></section><section class="business-card"><header><small>Competitive set</small><h3>Hospitality market</h3></header><div class="business-rivals"><article class="player"><span><strong>Dorra House</strong><small>${snapshot.marketShare}% market share</small></span><b>${Math.round(p.empire.reputation+empireStars(p)*1.8)}</b></article>${competitors}</div></section><section class="business-card business-history"><header><small>Recent performance</small><h3>Weekly trading record</h3></header>${history.length?`<div>${history.slice(0,10).reverse().map(item=>`<span title="Week ${item.week}: ${formatProgressMoney(item.net)} net"><i style="height:${Math.max(4,item.gross/max*100)}%"></i><b style="height:${Math.max(2,item.expenses/max*100)}%"></b><small>W${item.week}</small></span>`).join('')}</div>`:'<p>Close the first business week to begin the trading record.</p>'}</section><section class="business-card"><header><small>Portfolio effects</small><h3>Active venue synergies</h3></header><div class="business-synergies">${snapshot.synergies.length?snapshot.synergies.map(item=>`<article><b>+${Math.round(item.boost*100)}%</b><span><strong>${item.name}</strong><small>${item.venues.map(id=>EMPIRE_VENUES.find(venue=>venue.id===id)?.name).join(' + ')}</small></span></article>`).join(''):'<p>Open complementary venues to create portfolio synergies.</p>'}</div></section></div>`}
function empireOperationsHTML(p,snapshot){if(!snapshot.venues.length)return '<section class="business-empty"><h3>Open your first venue</h3><p>Staffing, demand, and specialisation controls appear when a venue begins operating.</p></section>';return `<div class="business-venue-grid">${snapshot.venues.map(metrics=>{let entry=p.empire.venues[metrics.id],venue=EMPIRE_VENUES.find(item=>item.id===metrics.id),specializations=EMPIRE_SPECIALIZATIONS[metrics.id]||[];return `<article class="business-venue"><header><div><small>Level ${entry.level} · ${metrics.utilisation}% utilised</small><h3>${venue.name}</h3></div><strong class="${metrics.net<0?'negative':''}">${metrics.net<0?'−':''}${formatProgressMoney(Math.abs(metrics.net))}/h net</strong></header><div class="business-venue-numbers"><span><small>Revenue</small><b>${formatProgressMoney(metrics.gross)}</b></span><span><small>Expenses</small><b>${formatProgressMoney(metrics.expenses)}</b></span><span><small>Satisfaction</small><b>${metrics.satisfaction}%</b></span></div><section><small>Staffing · ${metrics.staffTotal}/${metrics.staffTarget} recommended</small>${EMPIRE_STAFF_ROLES.map(role=>`<div class="business-staff-row"><span><strong>${role.name}</strong><small>${role.copy} · ${formatProgressMoney(role.wage)}/h wage</small></span><button data-business-staff-release="${role.id}" data-business-venue="${metrics.id}" ${entry.staff?.[role.id]?'':'disabled'}>−</button><b>${entry.staff?.[role.id]||0}</b><button data-business-staff-hire="${role.id}" data-business-venue="${metrics.id}" ${state.balance<role.hireCost?'disabled':''}>+</button></div>`).join('')}</section><section class="business-specialization"><small>Level 3 specialisation · permanent</small>${entry.level<3?'<p>Reach Level 3 to specialise this venue.</p>':entry.specialization?`<p><strong>${specializations.find(item=>item.id===entry.specialization)?.name}</strong> · ${specializations.find(item=>item.id===entry.specialization)?.copy}</p>`:`<div>${specializations.map(option=>`<button data-business-specialize="${option.id}" data-business-venue="${metrics.id}"><strong>${option.name}</strong><small>${option.copy}</small></button>`).join('')}</div>`}</section></article>`}).join('')}</div>`}
function empireMarketingHTML(p,snapshot){return `<div class="business-marketing-layout"><section class="business-card"><header><small>Acquire demand</small><h3>Marketing campaigns</h3></header><div class="business-campaigns">${EMPIRE_MARKETING_CAMPAIGNS.map(campaign=>{let active=p.empire.marketing.find(item=>item.id===campaign.id),segment=EMPIRE_CUSTOMER_SEGMENTS.find(item=>item.id===campaign.segment);return `<article class="${active?'active':''}"><header><span><small>${segment.name}</small><strong>${campaign.name}</strong></span><b>+${Math.round(campaign.boost*100)}%</b></header><p>${campaign.copy}</p><button data-business-marketing="${campaign.id}" ${active||state.balance<campaign.cost?'disabled':''}>${active?`${active.weeks} weeks remaining`:`Launch · ${formatProgressMoney(campaign.cost)}`}</button></article>`}).join('')}</div></section><section class="business-card"><header><small>Current response</small><h3>Demand forecast</h3></header><div class="business-segments">${EMPIRE_CUSTOMER_SEGMENTS.map(segment=>`<article><span><strong>${segment.name}</strong><small>${p.empire.marketing.some(item=>EMPIRE_MARKETING_CAMPAIGNS.find(campaign=>campaign.id===item.id)?.segment===segment.id)?'Campaign active':'Organic demand'}</small></span><b>${Math.round((snapshot.segmentDemand[segment.id]||1)*100)}%</b><i><em style="width:${Math.min(100,(snapshot.segmentDemand[segment.id]||1)*75)}%"></em></i></article>`).join('')}</div></section></div>`}
function empireFinanceHTML(p,snapshot){return `<div class="business-finance-grid"><section class="business-card"><header><small>Weekly projection</small><h3>Profit & loss</h3></header><dl class="business-pnl"><div><dt>Gross venue revenue</dt><dd>${formatProgressMoney(snapshot.weekly.gross)}</dd></div><div><dt>Operating costs and wages</dt><dd>−${formatProgressMoney(snapshot.weekly.expenses-snapshot.loanWeekly)}</dd></div><div><dt>Loan repayments</dt><dd>−${formatProgressMoney(snapshot.loanWeekly)}</dd></div><div class="total"><dt>Projected net profit</dt><dd class="${snapshot.weekly.net<0?'negative':''}">${snapshot.weekly.net<0?'−':''}${formatProgressMoney(Math.abs(snapshot.weekly.net))}</dd></div></dl></section><section class="business-card"><header><small>Funding</small><h3>Loans and investors</h3></header><div class="business-loans">${EMPIRE_LOANS.map(loan=>{let active=p.empire.loans.find(item=>item.id===loan.id);return `<article class="${active?'active':''}"><span><strong>${loan.name}</strong><small>${loan.copy}</small><em>${formatProgressMoney(loan.repayment)}/week for ${loan.weeks} weeks</em></span><button data-business-loan="${loan.id}" ${active?'disabled':''}>${active?`${active.weeks} payments left`:`Borrow ${formatProgressMoney(loan.principal)}`}</button></article>`}).join('')}</div></section></div>`}
function empireObjectivesHTML(p){let objectives=empireObjectiveStatus(p);return `<section class="business-card"><header><small>Independent Empire progression</small><h3>Business objectives</h3></header><div class="business-objectives">${objectives.map(item=>`<article class="${item.complete?'complete':''} ${item.claimed?'claimed':''}"><i>${item.claimed?'✓':item.complete?'!':'○'}</i><span><strong>${item.name}</strong><small>${item.copy}</small></span><b>${formatProgressMoney(item.reward)}</b><button data-business-objective="${item.id}" ${!item.complete||item.claimed?'disabled':''}>${item.claimed?'Claimed':item.complete?'Claim reward':'In progress'}</button></article>`).join('')}</div></section>`}
function renderEmpireManagement(p){let snapshot=businessSnapshot(p),quarter=Math.floor((p.empire.week-1)/13)+1,views=[['overview','Dashboard'],['operations','Operations'],['marketing','Marketing'],['finance','Finance'],['objectives','Objectives']],content=empireManagementView==='operations'?empireOperationsHTML(p,snapshot):empireManagementView==='marketing'?empireMarketingHTML(p,snapshot):empireManagementView==='finance'?empireFinanceHTML(p,snapshot):empireManagementView==='objectives'?empireObjectivesHTML(p):empireOverviewHTML(p,snapshot);return `<section class="business-management"><header class="business-management-head"><div><small>Business calendar · Year ${p.empire.year}, Q${quarter}</small><h2>Week ${p.empire.week} management meeting</h2><p>Plan the estate, close the week, respond to events, and reinvest the result.</p></div><button data-business-advance ${p.empire.event?'disabled':''}><strong>Close business week</strong><small>${p.empire.event?'Decision required first':`${snapshot.weekly.net<0?'−':''}${formatProgressMoney(Math.abs(snapshot.weekly.net))} projected net`}</small></button></header><nav class="business-management-nav" aria-label="Business management sections">${views.map(([id,label])=>`<button data-business-view="${id}" class="${empireManagementView===id?'active':''}" aria-pressed="${empireManagementView===id}">${label}</button>`).join('')}</nav><div class="business-management-body">${content}</div></section>`}
function renderEmpirePanel(){let p=state.progress,empire=p.empire,claimable=accrueEmpire(p),cap=empireCapHours(p),usedHours=(empire.unclaimedMs||0)/3600000,stars=empireStars(p),perks=empirePerks(p),snapshot=businessSnapshot(p),statuses=Object.fromEntries(['operating','available','locked'].map(status=>[status,EMPIRE_VENUES.filter(venue=>empireVenueStatus(venue,p)===status).length])),filtered=empireFilter==='all'?EMPIRE_VENUES:EMPIRE_VENUES.filter(venue=>empireVenueStatus(venue,p)===empireFilter);if(!filtered.some(venue=>venue.id===empireSelectedVenue))empireSelectedVenue=filtered[0]?.id||EMPIRE_VENUES[0].id;let selected=EMPIRE_VENUES.find(venue=>venue.id===empireSelectedVenue)||EMPIRE_VENUES[0],next=empireNextMove(p,claimable),effects=[['VIP cash',`+${Math.round(perks.contractCashPct*100)}%`],['VIP XP',`+${Math.round(perks.contractXpPct*100)}%`],['Motor discount',`${Math.round(perks.vehicleDiscountPct*100)}%`],['Boutique discount',`${Math.round(perks.boutiqueDiscountPct*100)}%`],['Racing cash',`+${Math.round(perks.racingCashPct*100)}%`],['Offline bank',`${perks.offlineCapHours}h`]];$('#empirePanel').innerHTML=`<div class="empire-command-bar" aria-label="Estate command summary"><div><span>Available capital</span><strong>${formatProgressMoney(state.balance)}</strong><small>Ready to invest</small></div><div><span>Net profit / hour</span><strong>${formatProgressMoney(snapshot.net)}</strong><small>${formatProgressMoney(snapshot.gross)} gross revenue</small></div><div><span>Ready to collect</span><strong id="empireReadyValue">${formatProgressMoney(claimable)}</strong><small id="empireBankCopy">${usedHours.toFixed(1)} of ${cap} hours banked</small><i class="empire-bank-track" aria-hidden="true"><b id="empireBankFill" style="width:${Math.min(100,usedHours/cap*100)}%"></b></i></div><div><span>Estate investment</span><strong>${formatProgressMoney(empireValue())}</strong><small>${stars} Empire star${stars===1?'':'s'} · one per level</small></div><button data-empire-claim ${claimable<1?'disabled':''}><span>Collect profit</span><small>${formatProgressMoney(empire.lifetimeEarned)} lifetime</small></button></div>${renderEmpireManagement(p)}<section class="empire-next"><div class="empire-next-mark" aria-hidden="true">✦</div><div><small>${next.eyebrow}</small><h2>${next.title}</h2><p>${next.copy}</p></div><span>${statuses.operating} operating · ${statuses.available} ready · ${statuses.locked} locked</span>${empireActionButton(next)}</section><div class="empire-workspace"><aside class="empire-portfolio" aria-label="Estate portfolio"><header><div><small>Estate portfolio</small><h2>Six Dorra venues</h2></div><strong>${stars} / 30 stars</strong></header><nav class="empire-filters" aria-label="Filter venues">${[['all','All',EMPIRE_VENUES.length],['operating','Operating',statuses.operating],['available','Available',statuses.available],['locked','Locked',statuses.locked]].map(([id,label,count])=>`<button class="${empireFilter===id?'active':''}" data-empire-filter="${id}" aria-pressed="${empireFilter===id}">${label}<span>${count}</span></button>`).join('')}</nav><div class="empire-portfolio-list" role="listbox" aria-label="Dorra venues">${filtered.length?filtered.map(venue=>renderEmpireVenueRow(venue,p)).join(''):'<p>No venues match this view yet.</p>'}</div><p class="empire-portfolio-note">Venue levels earn Empire stars, and those stars open larger properties.</p></aside>${renderEmpireDetail(selected,p)}</div><section class="empire-effects-bar"><header><small>House-wide effects</small><strong>How the estate improves every path</strong></header><div>${effects.map(([label,value])=>`<span><small>${label}</small><strong>${value}</strong></span>`).join('')}</div></section>`}
