function resetContractAttempt(id){let c=state.progress.contracts,contract=VIP_CONTRACTS.find(item=>item.id===id),reward=contract&&contractReward(state.progress,contract);c.activeId=id;c.status='active';c.stepIndex=0;c.stepProgress=0;c.stepSeen=[];c.attemptRounds=0;c.attempts++;c.rewardCash=reward?.cash||0;c.rewardXp=reward?.xp||0}
