const renderHudFullBalance=renderHud;
renderHud=()=>{renderHudFullBalance();let balance=$('#balance'),value=Math.max(0,Number(state.balance)||0),compact=value>=1e9?`$${(value/1e9).toFixed(value>=10e9?1:2)}B`:value>=1e6?`$${(value/1e6).toFixed(value>=10e6?1:2)}M`:money(value);balance.textContent=compact;balance.title=money(value);balance.setAttribute('aria-label',`Balance ${money(value)}`)};
const empireOverviewCoreHTML=empireOverviewHTML;
empireOverviewHTML=(p,snapshot)=>`<div class="business-quick-actions"><span><small>Management shortcuts</small><strong>Choose where to work next</strong></span><button data-business-view="portfolio">Manage venues</button><button data-business-view="upgrades">Review upgrades</button></div>${empireOverviewCoreHTML(p,snapshot)}`;
empireOperationsHTML=(p,snapshot)=>{if(!snapshot.venues.length)return '<section class="business-empty"><h3>Open your first venue</h3><p>Staffing, demand, and specialisation controls appear when a venue begins operating.</p><button data-business-view="portfolio">Open estate portfolio</button></section>';return `<div class="business-venue-grid">${snapshot.venues.map(metrics=>{let entry=p.empire.venues[metrics.id],venue=EMPIRE_VENUES.find(item=>item.id===metrics.id),specializations=EMPIRE_SPECIALIZATIONS[metrics.id]||[];return `<article class="business-venue"><header><div><small>Level ${entry.level} · ${metrics.utilisation}% utilised</small><h3>${venue.name}</h3></div><strong class="${metrics.net<0?'negative':''}">${metrics.net<0?'−':''}${formatProgressMoney(Math.abs(metrics.net))}/h net</strong></header><div class="business-venue-numbers"><span><small>Revenue</small><b>${formatProgressMoney(metrics.gross)}</b></span><span><small>Expenses</small><b>${formatProgressMoney(metrics.expenses)}</b></span><span><small>Satisfaction</small><b>${metrics.satisfaction}%</b></span></div><section><small>Staffing · ${metrics.staffTotal}/${metrics.staffTarget} recommended</small>${EMPIRE_STAFF_ROLES.map(role=>`<div class="business-staff-row"><span><strong>${role.name}</strong><small>${role.copy} · ${formatProgressMoney(role.wage)}/h wage</small></span><button aria-label="Release one ${role.name} team member" title="Release one" data-business-staff-release="${role.id}" data-business-venue="${metrics.id}" ${entry.staff?.[role.id]?'':'disabled'}>−</button><b aria-label="${entry.staff?.[role.id]||0} assigned">${entry.staff?.[role.id]||0}</b><button aria-label="Hire one ${role.name} team member for ${formatProgressMoney(role.hireCost)}" title="Hire for ${formatProgressMoney(role.hireCost)}" data-business-staff-hire="${role.id}" data-business-venue="${metrics.id}" ${state.balance<role.hireCost?'disabled':''}>+</button></div>`).join('')}</section><section class="business-specialization"><small>Level 3 specialisation · permanent</small>${entry.level<3?'<p>Reach Level 3 to specialise this venue.</p>':entry.specialization?`<p><strong>${specializations.find(item=>item.id===entry.specialization)?.name}</strong> · ${specializations.find(item=>item.id===entry.specialization)?.copy}</p>`:`<div>${specializations.map(option=>`<button data-business-specialize="${option.id}" data-business-venue="${metrics.id}"><strong>${option.name}</strong><small>${option.copy}</small></button>`).join('')}</div>`}</section><footer class="business-venue-footer"><span>${EMPIRE_VENUE_IMPROVEMENTS.reduce((sum,item)=>sum+(entry.improvements?.[item.id]||0),0)} / 9 capital project levels</span><button data-business-view="upgrades">View venue upgrades</button></footer></article>`}).join('')}</div>`};
function empirePortfolioHTML(p,snapshot){let claimable=Math.floor(p.empire.pending||0),stars=empireStars(p),perks=empirePerks(p),statuses=Object.fromEntries(['operating','available','locked'].map(status=>[status,EMPIRE_VENUES.filter(venue=>empireVenueStatus(venue,p)===status).length])),filtered=empireFilter==='all'?EMPIRE_VENUES:EMPIRE_VENUES.filter(venue=>empireVenueStatus(venue,p)===empireFilter);if(!filtered.some(venue=>venue.id===empireSelectedVenue))empireSelectedVenue=filtered[0]?.id||EMPIRE_VENUES[0].id;let selected=EMPIRE_VENUES.find(venue=>venue.id===empireSelectedVenue)||EMPIRE_VENUES[0],next=empireNextMove(p,claimable),effects=[['VIP cash',`+${Math.round(perks.contractCashPct*100)}%`],['VIP XP',`+${Math.round(perks.contractXpPct*100)}%`],['Motor discount',`${Math.round(perks.vehicleDiscountPct*100)}%`],['Boutique discount',`${Math.round(perks.boutiqueDiscountPct*100)}%`],['Racing cash',`+${Math.round(perks.racingCashPct*100)}%`],['Offline bank',`${perks.offlineCapHours}h`]];return `<section class="empire-next"><div class="empire-next-mark" aria-hidden="true">✦</div><div><small>${next.eyebrow}</small><h2>${next.title}</h2><p>${next.copy}</p></div><span>${statuses.operating} operating · ${statuses.available} ready · ${statuses.locked} locked</span>${empireActionButton(next)}</section><div class="empire-workspace"><aside class="empire-portfolio" aria-label="Estate portfolio"><header><div><small>Estate portfolio</small><h2>Six Dorra venues</h2></div><strong>${stars} / 30 stars</strong></header><nav class="empire-filters" aria-label="Filter venues">${[['all','All',EMPIRE_VENUES.length],['operating','Operating',statuses.operating],['available','Available',statuses.available],['locked','Locked',statuses.locked]].map(([id,label,count])=>`<button class="${empireFilter===id?'active':''}" data-empire-filter="${id}" aria-pressed="${empireFilter===id}">${label}<span>${count}</span></button>`).join('')}</nav><div class="empire-portfolio-list" role="listbox" aria-label="Dorra venues">${filtered.length?filtered.map(venue=>renderEmpireVenueRow(venue,p)).join(''):'<p>No venues match this view yet.</p>'}</div><p class="empire-portfolio-note">Venue levels earn Empire stars, and those stars open larger properties.</p></aside>${renderEmpireDetail(selected,p)}</div><section class="empire-effects-bar"><header><small>House-wide effects</small><strong>How the estate improves every path</strong></header><div>${effects.map(([label,value])=>`<span><small>${label}</small><strong>${value}</strong></span>`).join('')}</div></section>`}
function upgradeLevelTrack(level,label){return `<span class="business-upgrade-track" role="progressbar" aria-label="${label} level ${level} of 3" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${level}">${[1,2,3].map(step=>`<i class="${step<=level?'complete':''}">${step<=level?'✓':step}</i>`).join('')}</span>`}
function empireUpgradesHTML(p,snapshot){let headquarters=p.empire.headquarters||{},hqLevels=EMPIRE_HEADQUARTERS_UPGRADES.reduce((sum,item)=>sum+(headquarters[item.id]||0),0),venueLevels=EMPIRE_VENUES.reduce((sum,venue)=>sum+EMPIRE_VENUE_IMPROVEMENTS.reduce((total,item)=>total+(p.empire.venues[venue.id]?.improvements?.[item.id]||0),0),0),operating=EMPIRE_VENUES.filter(venue=>p.empire.venues[venue.id]?.level);return `<div class="business-upgrade-summary"><span><small>Permanent upgrade investment</small><strong>${formatProgressMoney(empireUpgradeInvestment(p))}</strong></span><span><small>Headquarters roadmap</small><strong>${hqLevels} / ${EMPIRE_HEADQUARTERS_UPGRADES.length*3}</strong></span><span><small>Venue capital projects</small><strong>${venueLevels} / ${operating.length*EMPIRE_VENUE_IMPROVEMENTS.length*3||0}</strong></span></div><section class="business-card business-headquarters"><header><small>Estate-wide programs</small><h3>Headquarters roadmap</h3><p>Permanent upgrades apply to every current and future Dorra venue.</p></header><div class="business-upgrade-grid">${EMPIRE_HEADQUARTERS_UPGRADES.map(upgrade=>{let level=headquarters[upgrade.id]||0,cost=upgrade.costs[level]||0;return `<article class="business-upgrade-card ${level===3?'complete':''}"><header><span><small>${upgrade.department}</small><strong>${upgrade.name}</strong></span><b>Level ${level}/3</b></header><p>${upgrade.copy}</p><em>${upgrade.effectCopy}</em>${upgradeLevelTrack(level,upgrade.name)}<button data-business-hq-upgrade="${upgrade.id}" ${level===3||state.balance<cost?'disabled':''}>${level===3?'Roadmap complete':`Buy Level ${level+1} · ${formatProgressMoney(cost)}`}</button>${level<3&&state.balance<cost?`<small class="business-shortfall">Need ${formatProgressMoney(cost-state.balance)} more capital</small>`:''}</article>`}).join('')}</div></section><section class="business-card business-capital-projects"><header><small>Property improvements</small><h3>Venue capital projects</h3><p>Each operating venue has nine additional permanent project levels.</p></header>${operating.length?`<div class="business-venue-upgrades">${operating.map(venue=>{let entry=p.empire.venues[venue.id],metrics=snapshot.venues.find(item=>item.id===venue.id);return `<article><header><span aria-hidden="true">${venue.icon}</span><div><small>${venue.area} · Level ${entry.level}</small><strong>${venue.name}</strong></div><b>${formatProgressMoney(metrics?.net||0)}/h net</b></header><div>${EMPIRE_VENUE_IMPROVEMENTS.map(improvement=>{let level=entry.improvements?.[improvement.id]||0,cost=empireVenueImprovementCost(venue,improvement.id,level);return `<section class="${level===3?'complete':''}"><div><span><strong>${improvement.name}</strong><small>${improvement.effectCopy}</small></span><b>${level}/3</b></div><p>${improvement.copy}</p>${upgradeLevelTrack(level,`${venue.name} ${improvement.name}`)}<button data-business-venue-upgrade="${improvement.id}" data-business-venue="${venue.id}" ${level===3||state.balance<cost?'disabled':''}>${level===3?'Project complete':`Build Level ${level+1} · ${formatProgressMoney(cost)}`}</button></section>`}).join('')}</div></article>`}).join('')}</div>`:'<div class="business-empty"><h3>No capital projects available</h3><p>Open a venue from the Portfolio to unlock its property improvements.</p><button data-business-view="portfolio">Open estate portfolio</button></div>'}</section>`}
