$('#dorraOs').addEventListener('keydown',event=>{if(event.key!=='Tab')return;let focusable=$$('#dorraOs button:not([disabled]),#dorraOs input:not([disabled]),#dorraOs select:not([disabled]),#dorraOs [tabindex]:not([tabindex="-1"])').filter(element=>!element.closest('[hidden]')&&element.getClientRects().length),first=focusable[0],last=focusable.at(-1);if(!first)return;if(event.shiftKey&&(document.activeElement===first||!$('#dorraOs').contains(document.activeElement))){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});


// Keep the shared save authority alive until explicit game navigation is durable.
let gameNavigationPending=false;
document.addEventListener('click',async event=>{
  const link=event.target.closest('a[href]');
  if(!link||event.defaultPrevented||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
  const destination=new URL(link.href,location.href);
  if(destination.origin!==location.origin||!['football-manager.html','war-simulation.html','idle-airport.html'].includes(destination.pathname.split('/').pop()))return;
  event.preventDefault();if(gameNavigationPending)return;gameNavigationPending=true;
  try{await protectedWriteQueue;await vault.flush();if(saveFailed)throw new Error('Your latest save did not finish. Reload this tab before changing games.');vaultWorker.terminate();location.href=destination.href}
  catch(error){gameNavigationPending=false;toast(error.message)}
});

// Online Alpha controller. Every meaningful input is sent as an intent; the
