pocketTick=()=>onlineIntent('pocket-tick',{},false);
startDorraMarketClock=function(){stopDorraMarketClock();const delay=dorraMarketRate().ms;if(!delay)return;dorraMarketTimer=setInterval(()=>{const title=$('#dorraOsAppTitle').textContent;if($('#dorraOs').hidden||$('#dorraOsApp').hidden||!['Markets Pro','Bloomberg'].includes(title)){stopDorraMarketClock();return}if(!onlineBusy)void onlineIntent('market-tick',{},false)},Math.max(delay,2000))};
finishArrival=async function(skip=false){if(onlineBusy)return;const path=arrivalSelection,controls=$$('#arrivalScreen button'),enter=$('#arrivalEnterBtn'),label=enter.innerHTML;controls.forEach(button=>button.disabled=true);enter.textContent='Entering the House…';try{const result=await onlineIntent('arrival',{path,skip});if(!result){$('#arrivalNextStep').textContent='Your choice could not be saved. Please try again.';return}$('#arrivalScreen').hidden=true;$('.app-shell').inert=false;document.body.classList.remove('arrival-open');skip?showDashboard():arrivalChoices[path].destination()}finally{controls.forEach(button=>button.disabled=false);enter.innerHTML=label}};
closeStoryDialogue=function(){if(!storyDialogueState)return;const d=storyDialogueState;storyDialogueState=null;$('#storyDialogue').hidden=true;document.body.classList.remove('modal-open');d.lastFocus?.focus?.();void onlineIntent('story-dialogue',{missionId:d.mission.id,phase:d.phase},false)};
// Legacy developer controls are never used to authorize online changes.
developerConsoleHTML=()=>'';developerSession=false;
redeemDeveloperCode=async code=>{if(String(code).trim().startsWith('DH-')){try{const {adminRequest}=await import('./admin-client.js');await adminRequest('unlock',{code:String(code).trim()});$('#developerCodeInput').value='';location.assign(new URL('admin.html',location.href));}catch(error){codeFeedback={text:error.message,type:'error'};renderWebsiteSettings()}return}const result=await onlineIntent('code-redeem',{code});codeFeedback={text:result?.message||'That code could not be redeemed.',type:result?'success':'error'};renderWebsiteSettings()};
runDeveloperAction=()=>location.assign(new URL('admin.html',location.href));
window.addEventListener('submit',event=>{const form=event.target;if(!['iphoneForm','macbookForm'].includes(form.id))return;event.preventDefault();event.stopImmediatePropagation();if(form.id==='iphoneForm')void onlineIntent('phone-save',{id:activePhoneFamily,model:phoneVariant()[0],finish:optionValue('finish'),storage:optionValue('storage'),case:optionValue('case'),engraving:$('#engravingInput').value.trim(),wallpaper:optionValue('wallpaper')}).then(r=>{if(r)closeConfigurator()});else void onlineIntent('mac-save',{id:activeMacFamily,model:macModel().id,chip:macActiveTier().id,finish:macValue('macFinish'),memory:macValue('macMemory'),storage:macValue('macStorage'),display:macValue('macDisplay'),power:macValue('macPower'),wallpaper:macValue('macWallpaper')}).then(r=>{if(r)closeMacConfigurator()})},true);
window.addEventListener('click',event=>{
 const b=event.target.closest('button,[data-monte-card],[data-memory]');if(!b||b.disabled)return;let action,args={},after=null;
 const houseButtons={dealBtn:['bj','start'],hitBtn:['bj','hit'],standBtn:['bj','stand'],doubleBtn:['bj','double'],pokerDealBtn:['poker','start'],pokerPlayBtn:['poker','play'],pokerFoldBtn:['poker','fold'],holdemDealBtn:['holdem','start'],holdemCallBtn:['holdem','call'],holdemFoldBtn:['holdem','fold'],videoPokerDealBtn:['videopoker','start'],videoPokerDrawBtn:['videopoker','draw'],spinBtn:['roulette','play'],higherBtn:['highlow','play'],lowerBtn:['highlow','play'],rollBtn:['dice','play'],baccaratDealBtn:['baccarat','play'],sicboRollBtn:['sicbo','play'],slotsSpinBtn:['slots','play'],memoryStartBtn:['memory','start'],monteStartBtn:['monte','start'],raceStartBtn:['racing','play']};
 if(houseButtons[b.id]){event.preventDefault();event.stopImmediatePropagation();const [game,move]=houseButtons[b.id],extra={bj:{},poker:{},holdem:{},videopoker:{held:[...(state.videoPoker?.held||[])]},roulette:{choice:state.rouletteChoice},highlow:{choice:b.id==='higherBtn'?'higher':'lower'},dice:{choice:state.diceChoice},baccarat:{choice:state.baccaratChoice},sicbo:{choice:state.sicboChoice},slots:{machine:state.slotMachine},racing:{choice:state.raceChoice}}[game]||{};if((game==='slots'&&state.slotsSpinning)||(game==='racing'&&state.raceRunning))return;void onlineHouse(game,move,extra);return}
 if(b.hasAttribute('data-memory')){event.preventDefault();event.stopImmediatePropagation();if(onlineMemoryReveal.length!==2)void onlineHouse('memory','pick',{index:Number(b.dataset.memory)});return}
 if(b.hasAttribute('data-monte-card')){event.preventDefault();event.stopImmediatePropagation();if(monteReady)void onlineHouse('monte','pick',{index:Number(b.dataset.monteCard)});return}
 if(['dailyRewardBtn','rooftopRewardBtn'].includes(b.id)||b.dataset.osAction==='reward')action='daily-reward';
 if(b.id==='arrivalEnterBtn'||b.id==='arrivalSkipBtn'){event.preventDefault();event.stopImmediatePropagation();void finishArrival(b.id==='arrivalSkipBtn');return}
 if(b.id==='buyCarBtn'){action='car-save';args={id:motorState.car.id,trim:motorState.trim,upgrades:[...motorState.upgrades],paint:motorState.paint,aero:motorState.aero}}
 if(b.hasAttribute('data-shop')){const item=shop.find(x=>x.id===b.dataset.shop);if(item?.configurable||macbookFamilies[b.dataset.shop])return;action='shop-buy';args={id:b.dataset.shop}}
 if(b.hasAttribute('data-os-car')){action='display-car';args={id:b.dataset.osCar}}
 if(b.hasAttribute('data-os-device')){action='equip';args={id:b.dataset.osDevice}}
 if(b.hasAttribute('data-os-wallpaper')){action='wallpaper';args={id:dorraDeviceMode==='mac'?dorraActiveMac():dorraActivePhone(),wallpaper:b.dataset.osWallpaper}}
 if(b.hasAttribute('data-perk-buy')){action='perk-buy';args={id:b.dataset.perkBuy};after=()=>openDorraOsApp('perks')}
 if(b.hasAttribute('data-store-app')&&!dorraAppOwned(b.dataset.storeApp)){action='app-buy';args={id:b.dataset.storeApp};after=()=>openDorraOsApp(b.dataset.storeApp)}
 if(b.hasAttribute('data-market-tick'))action='market-tick';
 if(b.hasAttribute('data-pocket-refresh'))action='pocket-tick';
 if(b.hasAttribute('data-market-clear'))action='market-clear';
 if(b.hasAttribute('data-cancel-order')){action='market-cancel';args={id:b.dataset.cancelOrder}}
 if(b.hasAttribute('data-market-submit')||b.hasAttribute('data-limit-submit')||b.hasAttribute('data-advanced-submit')){action=b.hasAttribute('data-market-submit')?'market-trade':'market-order';args={symbol:dorraMarketUi.selected,side:dorraMarketUi.side,qty:Number(dorraMarketUi.qty),type:dorraMarketUi.orderType,limit:Number(dorraMarketUi.limitPrice),stop:Number(dorraMarketUi.stopPrice),tif:dorraMarketUi.timeInForce||'gtc'}}
 if(b.hasAttribute('data-pocket-trade')){action='pocket-trade';args={symbol:pocketUi.selected,qty:Number(pocketUi.qty),side:b.dataset.pocketTrade}}
 const estateAttrs={'data-empire-claim':'estate-claim','data-venue-upgrade':'estate-upgrade','data-venue-manager':'estate-manager','data-venue-focus':'estate-focus','data-business-staff-hire':'estate-staff-hire','data-business-staff-release':'estate-staff-release','data-business-specialize':'estate-specialization','data-business-marketing':'estate-marketing','data-business-loan':'estate-loan','data-business-event-choice':'estate-event','data-business-objective':'estate-objective','data-business-advance':'estate-week','data-business-hq-upgrade':'estate-headquarters-upgrade','data-business-venue-upgrade':'estate-venue-improvement'};
 for(const [attribute,intent]of Object.entries(estateAttrs))if(b.hasAttribute(attribute)){action=intent;args={venueId:b.dataset.venueUpgrade||b.dataset.venueManager||b.dataset.venueFocus||b.dataset.businessVenue,focusId:b.dataset.focus,roleId:b.dataset.businessStaffHire||b.dataset.businessStaffRelease,specializationId:b.dataset.businessSpecialize,campaignId:b.dataset.businessMarketing,loanId:b.dataset.businessLoan,choiceId:b.dataset.businessEventChoice,objectiveId:b.dataset.businessObjective,upgradeId:b.dataset.businessHqUpgrade,improvementId:b.dataset.businessVenueUpgrade}}
 if(['claim','upgrade','manager'].includes(b.dataset.empireNextAction)){action={claim:'estate-claim',upgrade:'estate-upgrade',manager:'estate-manager'}[b.dataset.empireNextAction];args={venueId:b.dataset.empireNextVenue}}
 for(const [attr,intent]of Object.entries({'data-contract-accept':'contract-accept','data-contract-retry':'contract-retry','data-contract-abandon':'contract-abandon','data-contract-claim':'contract-claim'}))if(b.hasAttribute(attr)){action=intent;args={contractId:b.dataset.contractAccept};if(intent==='contract-abandon'&&!confirm('Abandon the active VIP brief?'))return}
 if(b.hasAttribute('data-story-choice')){action='story-choice';args={choiceId:b.dataset.storyChoice}}
 if(b.hasAttribute('data-story-complete')){action='story-complete';after=result=>{if(result.missionId)openStoryDialogue(result.missionId,'completion')}}
 if(b.id==='saveAvatarBtn'){action='profile-save';args={profile:{...profileDraft,name:$('#profileNameInput').value.trim()||'House Guest',initial:($('#profileInitialInput').value.trim()||'D').slice(0,1)}};after=()=>{profileDraft={...state.progress.profile};renderAvatarCreator()}}
 if(b.id==='soundBtn'||b.hasAttribute('data-site-sound')||b.hasAttribute('data-os-sound')){action='settings';args={sound:b.id==='soundBtn'?!state.sound:(b.dataset.siteSound||b.dataset.osSound)==='on'}}
 if(b.hasAttribute('data-site-motion')){action='settings';args={motion:b.dataset.siteMotion==='on'}}
 if(b.hasAttribute('data-site-text')){action='settings';args={textSize:b.dataset.siteText}}
 if(b.id==='redeemCodeBtn'){event.preventDefault();event.stopImmediatePropagation();void redeemDeveloperCode($('#developerCodeInput').value);return}
 if(b.hasAttribute('data-dev-action')){event.preventDefault();event.stopImmediatePropagation();toast('Administrator tools will be added later.');return}
 if(b.id==='resetProgressBtn'&&resetProgressArmed&&$('#resetProgressInput')?.value==='Delete Progress'){action='reset';args={confirmation:'Delete Progress'};after=()=>{resetProgressArmed=false;closeProfile();resetBlackjack();openArrival()}}
 if(!action)return;event.preventDefault();event.stopImmediatePropagation();void onlineIntent(action,args).then(result=>{if(result&&after)after(result)});
},true);
window.addEventListener('change',event=>{if(!event.target.matches('[data-perk-rate-input]'))return;event.stopImmediatePropagation();void onlineIntent('perk-setting',{rate:dorraMarketRateOrder[Number(event.target.value)]||'normal'}).then(r=>{if(r)openDorraOsApp('perks')})},true);
for(const [game,round]of Object.entries(state.progress.activeHouseRounds||{}))onlineRestoreRound(game,round);
if(state.progress.highCard){state.highCard=state.progress.highCard;renderHigh(state.highCard)}
renderMemory();renderMonte(!monteReady);setSaveState('saved');

function dailyResetLabel(){const next=new Date();next.setUTCHours(24,0,0,0);return 'Resets at '+next.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}

$('#estateManagementNav').onclick=event=>{const button=event.target.closest('[data-estate-view]');if(!button)return;empireManagementView=button.dataset.estateView;showDorraProgression('empire');$('#estateWorkspaceTitle')?.focus();};

function moveEstateStatus(inEstate){const target=inEstate?$('.estate-sidebar'):document.body;for(const selector of ['.online-account','#saveIndicator']){const node=$(selector);if(node&&target)target.appendChild(node)}}

function moveHomeStatus(inHome){const target=inHome?$('#homeAccount'):document.body;for(const selector of ['.online-account','#saveIndicator']){const node=$(selector);if(node&&target)target.appendChild(node)}}
mountHomeWorkspace(tab=>showDorraProgression(tab));
if(!$('#lobby').hidden)moveHomeStatus(true);
